    t.firstOnLine = k === 0 || real[k - 1].line !== t.line;
    t.lastOnLine = k === real.length - 1 || real[k + 1].line !== t.line;
  }
  if (options.comments) {
    for (const t of tokens) if (t.kind === 'comment') t.firstOnLine = t.lastOnLine = false;
  }

  tokens.push({
    kind: 'eof',
    text: '',
    value: '',
    line,
    col: n - lineStart + 1,
    start: n,
    end: n,
    spaceBefore: true,
    spaceAfter: true,
    firstOnLine: false,
    lastOnLine: true,
  });
  return tokens;
}

