        if (open) ctx.stroke();
        ctx.beginPath();
        ctx.strokeStyle = s.color;
        ctx.lineWidth = s.width;
        style = st;
        open = true;
        lastX = NaN;
      }
      if (x0 !== lastX || y0 !== lastY) ctx.moveTo(x0, y0);
      lastX = this.sx(s.to[0]);
      lastY = this.sy(s.to[1]);
