          ctx.lineTo(x, h);
        } else {
          const y = Math.round(this.sy(v)) + 0.5;
          ctx.moveTo(0, y);
          ctx.lineTo(w, y);
        }
        ctx.stroke();
      }
    };
    lines(x0, x1, true);
    lines(y0, y1, false);

    // osie
    const ox = this.sx(0);
    const oy = this.sy(0);
    ctx.strokeStyle = pal.axis;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    if (ox >= 0 && ox <= w) {
      ctx.moveTo(Math.round(ox) + 0.5, 0);
      ctx.lineTo(Math.round(ox) + 0.5, h);
    }
    if (oy >= 0 && oy <= h) {
      ctx.moveTo(0, Math.round(oy) + 0.5);
      ctx.lineTo(w, Math.round(oy) + 0.5);
    }
    ctx.stroke();

    // opisy
