/* ───────────── motywy ───────────── */

:root {
  color-scheme: light;
  --bg: #f4efe4;
  --surface: #fffdf8;
  --surface-2: #f7f1e4;
  --ink: #1d2a26;
  --muted: #5b6a64;
  --border: #ddd4c1;
  --accent: #0f7a5d;
  --accent-strong: #0b5f48;
  --accent-ink: #ffffff;
  --accent-soft: #dcefe7;
  --accent-text: #0b6b52;
  --copper: #b8672a;
  --danger: #b3261e;
  --danger-soft: #fbe6e3;
  --danger-ink: #7d1a14;
  --ok-soft: #d8f0e1;
  --ok-ink: #14663a;
  --warn-soft: #fbecc9;
  --warn-ink: #77520a;
  --focus: #1769c2;
  --shadow: 0 6px 24px rgba(40, 32, 12, 0.14);

  /* płótno – papier jest jasny w obu motywach, żeby kolory programów były czytelne */
  --paper: #fbf8f0;
  --grid-minor: #eee8d8;
  --grid-major: #ded5bf;
  --axis: #a1987f;
  --canvas-label: #7d755f;
  --ghost: #6f8191;
  --axis-x: #c4483b;
  --axis-y: #2e9e5b;
  --axis-z: #2b6fb3;

  /* edytor */
  --ed-bg: #fffdf8;
  --ed-gutter: #f3ecdc;
  --ed-gutter-ink: #8f8670;
  --ed-band: rgba(15, 122, 93, 0.13);
  --ed-band-error: rgba(179, 38, 30, 0.1);
  --t-cmd: #0b6b52;
  --t-def: #86379c;
  --t-num: #a8480f;
  --t-str: #6d41a0;
  --t-com: #766f5c;
  --t-br: #b03a2e;
  --t-proc: #1c5ca8;
  --t-op: #5b6a64;

  --mono: ui-monospace, 'SF Mono', 'Cascadia Code', 'JetBrains Mono', Menlo, Consolas, 'Liberation Mono', monospace;
  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #0f1715;
  --surface: #16211e;
  --surface-2: #1b2a26;
  --ink: #e6eee9;
  --muted: #9bb0a7;
  --border: #2b3d37;
  --accent: #36bd93;
  --accent-strong: #52d1a9;
  --accent-ink: #04211a;
  --accent-soft: #1d3a31;
  --accent-text: #5fd8b3;
  --copper: #e0996a;
  --danger: #ff8f85;
  --danger-soft: #3a1c1a;
  --danger-ink: #ffc9c3;
  --ok-soft: #173a29;
  --ok-ink: #8fe0b2;
  --warn-soft: #3b3010;
  --warn-ink: #f2d27c;
  --focus: #7ab8ff;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);

  --paper: #ebe6d8;
  --grid-minor: #e1dbc9;
  --grid-major: #d1c9b3;
  --axis: #8c836b;
  --canvas-label: #6d654f;
  --ghost: #5f7384;
  --axis-x: #b83d30;
  --axis-y: #25894d;
  --axis-z: #2461a3;

  --ed-bg: #121c19;
  --ed-gutter: #172420;
  --ed-gutter-ink: #70877d;
  --ed-band: rgba(54, 189, 147, 0.16);
  --ed-band-error: rgba(255, 143, 133, 0.14);
  --t-cmd: #5fd8b3;
  --t-def: #d9a0ee;
  --t-num: #f0a46b;
  --t-str: #c4a0ee;
  --t-com: #7f948b;
  --t-br: #ff9a8f;
  --t-proc: #8fb8f5;
  --t-op: #9bb0a7;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --bg: #0f1715;
    --surface: #16211e;
    --surface-2: #1b2a26;
    --ink: #e6eee9;
    --muted: #9bb0a7;
    --border: #2b3d37;
    --accent: #36bd93;
    --accent-strong: #52d1a9;
    --accent-ink: #04211a;
    --accent-soft: #1d3a31;
    --accent-text: #5fd8b3;
    --copper: #e0996a;
    --danger: #ff8f85;
    --danger-soft: #3a1c1a;
    --danger-ink: #ffc9c3;
    --ok-soft: #173a29;
    --ok-ink: #8fe0b2;
    --warn-soft: #3b3010;
    --warn-ink: #f2d27c;
    --focus: #7ab8ff;
    --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);
    --paper: #ebe6d8;
    --grid-minor: #e1dbc9;
    --grid-major: #d1c9b3;
    --axis: #8c836b;
    --canvas-label: #6d654f;
    --ghost: #5f7384;
    --axis-x: #b83d30;
    --axis-y: #25894d;
    --axis-z: #2461a3;
    --ed-bg: #121c19;
    --ed-gutter: #172420;
    --ed-gutter-ink: #70877d;
    --ed-band: rgba(54, 189, 147, 0.16);
    --ed-band-error: rgba(255, 143, 133, 0.14);
    --t-cmd: #5fd8b3;
    --t-def: #d9a0ee;
    --t-num: #f0a46b;
    --t-str: #c4a0ee;
    --t-com: #7f948b;
    --t-br: #ff9a8f;
    --t-proc: #8fb8f5;
    --t-op: #9bb0a7;
  }
}

/* ───────────── podstawy ───────────── */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  height: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100%;
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--ink);
}

#app {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  margin: -1px;
  padding: 0;
  border: 0;
}

[hidden] {
  display: none !important;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -60px;
  z-index: 100;
  padding: 10px 16px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  font-weight: 700;
  text-decoration: none;
}
.skip-link:focus {
  top: 8px;
}

a {
  color: var(--accent-text);
}

.muted {
  color: var(--muted);
}

/* ───────────── nagłówek ───────────── */

.app-header {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px 20px;
  min-height: 56px;
  padding: 6px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  text-decoration: none;
  font-weight: 800;
  font-size: 1.3rem;
  letter-spacing: -0.01em;
}
.brand-name {
  background: linear-gradient(100deg, var(--accent-text), var(--copper));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.logo-mark {
  flex: none;
}

.main-nav {
  display: flex;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
.main-nav a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px;
  border-radius: 10px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 600;
  min-height: 40px;
}
.main-nav a:hover {
  background: var(--surface-2);
  color: var(--ink);
}
.main-nav a[aria-current='page'] {
  background: var(--accent-soft);
  color: var(--accent-text);
}

.header-actions {
  display: flex;
  gap: 6px;
  margin-left: auto;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--border);
}

.icon {
  flex: none;
}

/* ───────────── przyciski ───────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font-weight: 650;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
}
.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: color-mix(in srgb, var(--border) 60%, var(--ink));
}
.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}
.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn-small {
  min-height: 34px;
  padding: 4px 11px;
  font-size: 0.9rem;
}
.btn-ghost {
  background: transparent;
}

/* ───────────── pracownia ───────────── */

main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
main:focus {
  outline: none;
}

.workspace {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.toolbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  padding: 8px 12px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.seg {
  display: inline-flex;
  margin: 0;
  padding: 2px;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-2);
}
.seg-item {
  position: relative;
  display: block;
}
.seg-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.seg-item span {
  display: block;
  min-width: 52px;
  padding: 6px 14px;
  border-radius: 9px;
  text-align: center;
  font-weight: 750;
  letter-spacing: 0.02em;
  color: var(--muted);
}
.seg-input:checked + span {
  background: var(--accent);
  color: var(--accent-ink);
}
.seg-input:focus-visible + span {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.seg-input:disabled {
  cursor: not-allowed;
}
.seg-input:disabled:not(:checked) + span {
  opacity: 0.5;
}

.speed {
  gap: 8px;
}
.speed-label {
  font-size: 0.85rem;
  color: var(--muted);
  font-weight: 600;
}
.speed input[type='range'] {
  width: 120px;
  accent-color: var(--accent);
}
.speed-out {
  min-width: 7.5em;
  font-size: 0.85rem;
  color: var(--ink);
}

.select {
  height: 40px;
  padding: 0 32px 0 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  max-width: 190px;
  font-weight: 600;
  cursor: pointer;
}
.select:disabled {
  opacity: 0.5;
}
.select-wrap {
  display: flex;
}

.tool-files .btn-label {
  display: none;
}
.tool-files .btn {
  padding: 7px 10px;
}
.btn-tool .btn-label {
  display: inline;
}

.panes {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
  min-height: 0;
}

.pane {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
}

.pane-view {
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--paper);
  height: clamp(280px, 46vh, 520px);
  flex: none;
}

.view-host {
  position: relative;
  flex: 1;
  min-height: 0;
}

.view {
  position: absolute;
  inset: 0;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}
.view.dragging {
  cursor: grabbing;
}
.view:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.view canvas {
  display: block;
}

.view-controls {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.view-btn {
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  border-color: var(--border);
  backdrop-filter: blur(4px);
}

.view-info {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--surface);
  border-top: 1px solid var(--border);
  color: var(--muted);
  font: 12.5px/1.4 var(--mono);
  white-space: nowrap;
  overflow: hidden;
}
.info-swatch {
  flex: none;
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.35);
}
.info-text {
  overflow: hidden;
  text-overflow: ellipsis;
}

.pane-code {
  display: flex;
  flex-direction: column;
  background: var(--ed-bg);
  min-height: 360px;
}

.status {
  flex: none;
  padding: 7px 14px;
  border-top: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.88rem;
}

.error-bar {
  flex: none;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 14px;
  background: var(--danger-soft);
  color: var(--danger-ink);
  border-top: 1px solid color-mix(in srgb, var(--danger) 35%, transparent);
  font-size: 0.92rem;
}
.error-bar .icon {
  margin-top: 3px;
}
.error-jump {
  flex: none;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font-weight: 750;
  text-decoration: underline;
  cursor: pointer;
}
.error-text {
  min-width: 0;
}

@media (min-width: 900px) {
  .workspace {
    height: calc(100dvh - 57px);
    flex: none;
  }
  .panes {
    display: grid;
    grid-template-columns: minmax(340px, 5fr) 7fr;
    align-items: stretch;
  }
  .pane-view {
    order: 2;
    height: auto;
  }
  .pane-code {
    order: 1;
    min-height: 0;
  }
  main {
    min-height: 0;
  }
}

@media (max-width: 760px) {
  .app-header {
    gap: 8px;
    padding: 4px 8px;
  }
  .brand-name {
    font-size: 1.1rem;
  }
  .main-nav a span {
    display: none;
  }
  .main-nav a {
    padding: 8px 10px;
  }
  .toolbar {
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 10px;
    padding: 6px 8px;
    scrollbar-width: thin;
  }
  .toolbar > * {
    flex: none;
  }
  .btn-tool .btn-label {
    display: none;
  }
  .btn-tool {
    padding: 7px 11px;
  }
  .speed-label {
    display: none;
  }
  .panes {
    padding: 8px;
    gap: 8px;
  }
  .pane-view {
    height: clamp(240px, 40vh, 420px);
  }
}

@media (pointer: coarse) {
  .code-input,
  .code-highlight,
  .gutter,
  .measure {
    font-size: 16px !important;
    line-height: 24px !important;
  }
  :root {
    --ed-lh: 24px;
  }
}

/* ───────────── edytor ───────────── */

.editor {
  --ed-lh: 21px;
  --ed-pad: 10px;
  position: relative;
  flex: 1;
  display: flex;
  min-height: 220px;
  background: var(--ed-bg);
  font: 14px/var(--ed-lh) var(--mono);
}
@media (pointer: coarse) {
  .editor {
    --ed-lh: 24px;
    font-size: 16px;
  }
}
.editor:focus-within {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--focus) 70%, transparent);
}

.gutter {
  flex: none;
  position: relative;
  width: calc(var(--gutter-digits, 2) * 1ch + 22px);
  overflow: hidden;
  background: var(--ed-gutter);
  color: var(--ed-gutter-ink);
  text-align: right;
  user-select: none;
  -webkit-user-select: none;
  border-right: 1px solid var(--border);
}
.gutter-inner {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: var(--ed-pad) 10px var(--ed-pad) 0;
  will-change: transform;
}
.gutter-text {
  margin: 0;
  font: inherit;
  line-height: var(--ed-lh);
}
.gutter-active,
.gutter-error {
  position: absolute;
  left: 0;
  right: 0;
}
.gutter-active {
  background: var(--accent);
  opacity: 0.28;
}
.gutter-error {
  background: var(--danger);
  color: #fff;
  font-weight: 800;
  text-align: left;
  padding-left: 5px;
  line-height: var(--ed-lh);
  font-size: 12px;
}

.editor-body {
  position: relative;
  flex: 1;
  min-width: 0;
}
.layers {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.layers-inner {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  will-change: transform;
}
.band {
  position: absolute;
  left: 0;
  width: 100%;
  min-width: 100vw;
}
.band-active {
  background: var(--ed-band);
  box-shadow: inset 3px 0 0 var(--accent);
}
.band-error {
  background: var(--ed-band-error);
}
.code-highlight {
  position: relative;
  margin: 0;
  padding: var(--ed-pad) 14px var(--ed-pad) 12px;
  font: inherit;
  line-height: var(--ed-lh);
  white-space: pre;
  tab-size: 2;
  color: var(--ink);
}
.code-highlight code {
  font: inherit;
}
.code-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: var(--ed-pad) 14px var(--ed-pad) 12px;
  border: 0;
  outline: 0;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: var(--ink);
  font: inherit;
  line-height: var(--ed-lh);
  white-space: pre;
  tab-size: 2;
  letter-spacing: normal;
}
.code-input::selection {
  background: color-mix(in srgb, var(--focus) 35%, transparent);
  -webkit-text-fill-color: transparent;
}
.measure {
  position: absolute;
  visibility: hidden;
  white-space: pre;
  font: inherit;
  pointer-events: none;
}

.t-cmd {
  color: var(--t-cmd);
  font-weight: 650;
}
.t-def {
  color: var(--t-def);
  font-weight: 650;
}
.t-val {
  color: var(--t-num);
  font-weight: 650;
}
.t-num {
  color: var(--t-num);
}
.t-str {
  color: var(--t-str);
}
.t-color {
  border-bottom: 3px solid var(--swatch);
}
.t-com {
  color: var(--t-com);
  font-style: italic;
}
.t-br {
  color: var(--t-br);
  font-weight: 700;
}
.t-op {
  color: var(--t-op);
}
.t-proc {
  color: var(--t-proc);
  font-weight: 650;
}
.t-name {
  color: var(--ink);
}
.t-bad {
  color: var(--danger);
}
.err-mark {
  text-decoration: underline wavy var(--danger);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
  background: color-mix(in srgb, var(--danger) 16%, transparent);
  border-radius: 2px;
}
.err-point {
  position: relative;
  background: none;
  text-decoration: none;
}
.err-point::after {
  content: '';
  position: absolute;
  left: -2px;
  bottom: 0;
  width: 8px;
  height: 4px;
  border-bottom: 2px solid var(--danger);
}

.err-bubble {
  position: absolute;
  z-index: 4;
  max-width: min(560px, calc(100% - 12px));
  padding: 6px 10px;
  border-radius: 8px;
  background: #b3261e;
  color: #fff;
  font: 13px/1.4 var(--sans);
  box-shadow: var(--shadow);
  pointer-events: none;
}
.err-bubble::before {
  content: '';
  position: absolute;
  top: -5px;
  left: calc(var(--arrow-x, 14px) - 5px);
  border: 5px solid transparent;
  border-top: 0;
  border-bottom-color: #b3261e;
}
.err-bubble.above::before {
  top: auto;
  bottom: -5px;
  border-bottom: 0;
  border-top: 5px solid #b3261e;
  border-bottom-color: transparent;
}

/* ───────────── wyzwanie w pracowni ───────────── */

.challenge-host {
  flex: none;
  max-height: 46%;
  overflow: auto;
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}
.challenge-panel {
  padding: 12px 14px 14px;
}
.challenge-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.challenge-head h2 {
  margin: 0 8px 0 0;
  font-size: 1.15rem;
}
.challenge-panel p {
  margin: 8px 0;
}
.challenge-details {
  margin: 4px 0 8px;
  padding-left: 20px;
  color: var(--muted);
  font-size: 0.93rem;
}
.challenge-panel details {
  margin: 6px 0;
}
.challenge-panel summary {
  cursor: pointer;
  font-weight: 650;
  color: var(--accent-text);
}
.challenge-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 10px;
}
.check-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}
.check-label input {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}
.link-quiet {
  font-weight: 600;
}
.challenge-result {
  margin-top: 10px;
}
.challenge-result.pass,
.challenge-result.fail {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px 12px;
  border-radius: 10px;
}
.challenge-result.pass {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.challenge-result.fail {
  background: var(--danger-soft);
  color: var(--danger-ink);
}
.challenge-result p {
  margin: 2px 0 0;
}
.challenge-result .icon {
  margin-top: 2px;
}

/* ───────────── odznaki ───────────── */

.badge {
  display: inline-block;
  padding: 1px 9px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-text);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  vertical-align: middle;
  text-transform: uppercase;
}
.badge-ok {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.level-1 {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.level-2 {
  background: var(--warn-soft);
  color: var(--warn-ink);
}
.level-3 {
  background: var(--danger-soft);
  color: var(--danger-ink);
}

/* ───────────── strony ───────────── */

.page-host {
  flex: 1;
  min-width: 0;
}
.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 16px 72px;
}
.page-head h1 {
  margin: 0 0 6px;
  font-size: clamp(1.7rem, 4vw, 2.3rem);
  letter-spacing: -0.02em;
}
.lead {
  margin: 0 0 24px;
  max-width: 62ch;
  color: var(--muted);
  font-size: 1.05rem;
}
.group-title {
  margin: 28px 0 12px;
  font-size: 1.1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(255px, 1fr));
  gap: 16px;
}
.card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
}
.card-done {
  border-color: color-mix(in srgb, var(--ok-ink) 45%, var(--border));
}
.card .thumb {
  position: relative;
  inset: auto;
  width: 100%;
  height: 180px;
  cursor: default;
  pointer-events: none;
  border-bottom: 1px solid var(--border);
}
.card-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 14px 16px 16px;
}
.card-body h2 {
  margin: 0;
  font-size: 1.1rem;
}
.card-body p {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 0.95rem;
  flex: 1;
}

.progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  font-weight: 650;
}
.progress-bar {
  width: min(280px, 50vw);
  height: 10px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  overflow: hidden;
}
.progress-bar span {
  display: block;
  height: 100%;
  background: var(--accent);
}

/* opis języka */

.ref-layout {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr);
}
@media (min-width: 960px) {
  .ref-layout {
    grid-template-columns: 250px minmax(0, 1fr);
    align-items: start;
  }
  .toc {
    position: sticky;
    top: 70px;
    max-height: calc(100dvh - 90px);
    overflow: auto;
  }
}
.toc {
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
}
.toc-title {
  margin: 0 0 6px;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--muted);
}
.toc ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.toc li a {
  display: block;
  padding: 4px 0;
  text-decoration: none;
}
.toc li a:hover {
  text-decoration: underline;
}
.toc-sub {
  display: block;
  margin-top: 6px;
  font-size: 0.85rem;
  color: var(--muted);
}
.toc-cmds {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
}
.toc-cmds a {
  font-family: var(--mono);
  font-size: 0.9rem;
}

.ref-content {
  min-width: 0;
}
.ref-section {
  margin-bottom: 34px;
  scroll-margin-top: 70px;
}
.ref-section h2 {
  margin: 0 0 10px;
  font-size: 1.45rem;
  letter-spacing: -0.01em;
}
.ref-section p,
.ref-section li {
  max-width: 78ch;
}
.command {
  margin: 14px 0;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  scroll-margin-top: 70px;
}
.command header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.command h3 {
  margin: 0;
  font-size: 1.05rem;
}
.command h3 code {
  font-family: var(--mono);
  color: var(--accent-text);
}
.command p {
  margin: 6px 0;
}
.aliases {
  color: var(--muted);
  font-size: 0.92rem;
}
code.inline-code,
.ref-section p code,
.ref-section li code,
.ref-section td code {
  padding: 1px 6px;
  border-radius: 6px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  font: 0.88em var(--mono);
}
.note {
  padding: 10px 14px;
  border-left: 4px solid var(--copper);
  background: var(--surface-2);
  border-radius: 0 10px 10px 0;
}

.sample {
  margin: 10px 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: var(--ed-bg);
}
.code-sample {
  margin: 0;
  padding: 10px 14px;
  overflow-x: auto;
  font: 13.5px/1.55 var(--mono);
  white-space: pre;
  tab-size: 2;
  color: var(--ink);
}
.sample-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  background: var(--ed-gutter);
  border-top: 1px solid var(--border);
}

.table-wrap {
  overflow-x: auto;
  margin: 10px 0;
}
table {
  width: 100%;
  border-collapse: collapse;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: 0.95rem;
}
th,
td {
  padding: 8px 12px;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--border);
}
th {
  background: var(--surface-2);
  font-weight: 700;
}
tr:last-child td {
  border-bottom: 0;
}
kbd {
  display: inline-block;
  min-width: 1.7em;
  padding: 1px 7px;
  border: 1px solid var(--border);
  border-bottom-width: 3px;
  border-radius: 6px;
  background: var(--surface-2);
  font: 600 0.85em var(--mono);
  text-align: center;
}
.keys {
  white-space: nowrap;
}

/* ───────────── okna i powiadomienia ───────────── */

.dialog {
  width: min(520px, calc(100vw - 24px));
  padding: 20px 22px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}
.dialog-wide {
  width: min(680px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(8, 16, 13, 0.6);
}
.dialog-title {
  margin: 0 0 10px;
  font-size: 1.25rem;
}
.dialog-body p {
  margin: 8px 0;
}
.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}
.share-input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-2);
  font: 13px var(--mono);
}
.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.history-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 10px;
}
.history-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  font-size: 0.9rem;
}
.history-meta code {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-family: var(--mono);
}

.toasts {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(560px, calc(100vw - 24px));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 16px;
  border-radius: 12px;
  background: #1d2a26;
  color: #f0f5f2;
  box-shadow: var(--shadow);
  pointer-events: auto;
  animation: toast-in 0.2s ease-out;
}
.toast span {
  flex: 1;
}
.toast .btn {
  color: #9be6cd;
  border-color: #9be6cd55;
}
.toast .btn:hover:not(:disabled) {
  background: #ffffff18;
}
.toast .toast-close {
  color: #f0f5f2;
  width: 32px;
  height: 32px;
}
.toast .toast-close:hover {
  background: #ffffff22;
}
.toast-error {
  background: #7d1a14;
}
.toast-success {
  background: #11513b;
}
.toast.leaving {
  opacity: 0;
  transition: opacity 0.2s;
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

toolu_01UGxFypHzoiU1hPqvsyAxDK.content:
/* ───────────── motywy ───────────── */

:root {
  color-scheme: light;
  --bg: #f4efe4;
  --surface: #fffdf8;
  --surface-2: #f7f1e4;
  --ink: #1d2a26;
  --muted: #5b6a64;
  --border: #ddd4c1;
  --accent: #0f7a5d;
  --accent-strong: #0b5f48;
  --accent-ink: #ffffff;
  --accent-soft: #dcefe7;
  --accent-text: #0b6b52;
  --copper: #b8672a;
  --danger: #b3261e;
  --danger-soft: #fbe6e3;
  --danger-ink: #7d1a14;
  --ok-soft: #d8f0e1;
  --ok-ink: #14663a;
  --warn-soft: #fbecc9;
  --warn-ink: #77520a;
  --focus: #1769c2;
  --shadow: 0 6px 24px rgba(40, 32, 12, 0.14);

  /* płótno – papier jest jasny w obu motywach, żeby kolory programów były czytelne */
  --paper: #fbf8f0;
  --grid-minor: #eee8d8;
  --grid-major: #ded5bf;
  --axis: #a1987f;
  --canvas-label: #7d755f;
  --ghost: #6f8191;
  --axis-x: #c4483b;
  --axis-y: #2e9e5b;
  --axis-z: #2b6fb3;

  /* edytor */
  --ed-bg: #fffdf8;
  --ed-gutter: #f3ecdc;
  --ed-gutter-ink: #8f8670;
  --ed-band: rgba(15, 122, 93, 0.13);
  --ed-band-error: rgba(179, 38, 30, 0.1);
  --t-cmd: #0b6b52;
  --t-def: #86379c;
  --t-num: #a8480f;
  --t-str: #6d41a0;
  --t-com: #766f5c;
  --t-br: #b03a2e;
  --t-proc: #1c5ca8;
  --t-op: #5b6a64;

  --mono: ui-monospace, 'SF Mono', 'Cascadia Code', 'JetBrains Mono', Menlo, Consolas, 'Liberation Mono', monospace;
  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #0f1715;
  --surface: #16211e;
  --surface-2: #1b2a26;
  --ink: #e6eee9;
  --muted: #9bb0a7;
  --border: #2b3d37;
  --accent: #36bd93;
  --accent-strong: #52d1a9;
  --accent-ink: #04211a;
  --accent-soft: #1d3a31;
  --accent-text: #5fd8b3;
  --copper: #e0996a;
  --danger: #ff8f85;
  --danger-soft: #3a1c1a;
  --danger-ink: #ffc9c3;
  --ok-soft: #173a29;
  --ok-ink: #8fe0b2;
  --warn-soft: #3b3010;
  --warn-ink: #f2d27c;
  --focus: #7ab8ff;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);

  --paper: #ebe6d8;
  --grid-minor: #e1dbc9;
  --grid-major: #d1c9b3;
  --axis: #8c836b;
  --canvas-label: #6d654f;
  --ghost: #5f7384;
  --axis-x: #b83d30;
  --axis-y: #25894d;
  --axis-z: #2461a3;

  --ed-bg: #121c19;
  --ed-gutter: #172420;
  --ed-gutter-ink: #70877d;
  --ed-band: rgba(54, 189, 147, 0.16);
  --ed-band-error: rgba(255, 143, 133, 0.14);
  --t-cmd: #5fd8b3;
  --t-def: #d9a0ee;
  --t-num: #f0a46b;
  --t-str: #c4a0ee;
  --t-com: #7f948b;
  --t-br: #ff9a8f;
  --t-proc: #8fb8f5;
  --t-op: #9bb0a7;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --bg: #0f1715;
    --surface: #16211e;
    --surface-2: #1b2a26;
    --ink: #e6eee9;
    --muted: #9bb0a7;
    --border: #2b3d37;
    --accent: #36bd93;
    --accent-strong: #52d1a9;
    --accent-ink: #04211a;
    --accent-soft: #1d3a31;
    --accent-text: #5fd8b3;
    --copper: #e0996a;
    --danger: #ff8f85;
    --danger-soft: #3a1c1a;
    --danger-ink: #ffc9c3;
    --ok-soft: #173a29;
    --ok-ink: #8fe0b2;
    --warn-soft: #3b3010;
    --warn-ink: #f2d27c;
    --focus: #7ab8ff;
    --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);
    --paper: #ebe6d8;
    --grid-minor: #e1dbc9;
    --grid-major: #d1c9b3;
    --axis: #8c836b;
    --canvas-label: #6d654f;
    --ghost: #5f7384;
    --axis-x: #b83d30;
    --axis-y: #25894d;
    --axis-z: #2461a3;
    --ed-bg: #121c19;
    --ed-gutter: #172420;
    --ed-gutter-ink: #70877d;
    --ed-band: rgba(54, 189, 147, 0.16);
    --ed-band-error: rgba(255, 143, 133, 0.14);
    --t-cmd: #5fd8b3;
    --t-def: #d9a0ee;
    --t-num: #f0a46b;
    --t-str: #c4a0ee;
    --t-com: #7f948b;
    --t-br: #ff9a8f;
    --t-proc: #8fb8f5;
    --t-op: #9bb0a7;
  }
}

/* ───────────── podstawy ───────────── */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  height: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100%;
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--ink);
}

#app {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  margin: -1px;
  padding: 0;
  border: 0;
}

[hidden] {
  display: none !important;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -60px;
  z-index: 100;
  padding: 10px 16px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  font-weight: 700;
  text-decoration: none;
}
.skip-link:focus {
  top: 8px;
}

a {
  color: var(--accent-text);
}

.muted {
  color: var(--muted);
}

/* ───────────── nagłówek ───────────── */

.app-header {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px 20px;
  min-height: 56px;
  padding: 6px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  text-decoration: none;
  font-weight: 800;
  font-size: 1.3rem;
  letter-spacing: -0.01em;
}
.brand-name {
  background: linear-gradient(100deg, var(--accent-text), var(--copper));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.logo-mark {
  flex: none;
}

.main-nav {
  display: flex;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
.main-nav a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px;
  border-radius: 10px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 600;
  min-height: 40px;
}
.main-nav a:hover {
  background: var(--surface-2);
  color: var(--ink);
}
.main-nav a[aria-current='page'] {
  background: var(--accent-soft);
  color: var(--accent-text);
}

.header-actions {
  display: flex;
  gap: 6px;
  margin-left: auto;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--border);
}

.icon {
  flex: none;
}

/* ───────────── przyciski ───────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font-weight: 650;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
}
.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: color-mix(in srgb, var(--border) 60%, var(--ink));
}
.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}
.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn-small {
  min-height: 34px;
  padding: 4px 11px;
  font-size: 0.9rem;
}
.btn-ghost {
  background: transparent;
}

/* ───────────── pracownia ───────────── */

main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
main:focus {
  outline: none;
}

.workspace {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.toolbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  padding: 8px 12px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.seg {
  display: inline-flex;
  margin: 0;
  padding: 2px;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-2);
}
.seg-item {
  position: relative;
  display: block;
}
.seg-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.seg-item span {
  display: block;
  min-width: 52px;
  padding: 6px 14px;
  border-radius: 9px;
  text-align: center;
  font-weight: 750;
  letter-spacing: 0.02em;
  color: var(--muted);
}
.seg-input:checked + span {
  background: var(--accent);
  color: var(--accent-ink);
}
.seg-input:focus-visible + span {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.seg-input:disabled {
  cursor: not-allowed;
}
.seg-input:disabled:not(:checked) + span {
  opacity: 0.5;
}

.speed {
  gap: 8px;
}
.speed-label {
  font-size: 0.85rem;
  color: var(--muted);
  font-weight: 600;
}
.speed input[type='range'] {
  width: 120px;
  accent-color: var(--accent);
}
.speed-out {
  min-width: 7.5em;
  font-size: 0.85rem;
  color: var(--ink);
}

.select {
  height: 40px;
  padding: 0 32px 0 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  max-width: 190px;
  font-weight: 600;
  cursor: pointer;
}
.select:disabled {
  opacity: 0.5;
}
.select-wrap {
  display: flex;
}

.tool-files .btn-label {
  display: none;
}
.tool-files .btn {
  padding: 7px 10px;
}
.btn-tool .btn-label {
  display: inline;
}

.panes {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
  min-height: 0;
}

.pane {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
}

.pane-view {
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--paper);
  height: clamp(280px, 46vh, 520px);
  flex: none;
}

.view-host {
  position: relative;
  flex: 1;
  min-height: 0;
}

.view {
  position: absolute;
  inset: 0;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}
.view.dragging {
  cursor: grabbing;
}
.view:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.view canvas {
  display: block;
}

.view-controls {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.view-btn {
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  border-color: var(--border);
  backdrop-filter: blur(4px);
}

.view-info {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--surface);
  border-top: 1px solid var(--border);
  color: var(--muted);
  font: 12.5px/1.4 var(--mono);
  white-space: nowrap;
  overflow: hidden;
}
.info-swatch {
  flex: none;
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.35);
}
.info-text {
  overflow: hidden;
  text-overflow: ellipsis;
}

.pane-code {
  display: flex;
  flex-direction: column;
  background: var(--ed-bg);
  min-height: 360px;
}

.status {
  flex: none;
  padding: 7px 14px;
  border-top: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.88rem;
}

.error-bar {
  flex: none;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 14px;
  background: var(--danger-soft);
  color: var(--danger-ink);
  border-top: 1px solid color-mix(in srgb, var(--danger) 35%, transparent);
  font-size: 0.92rem;
}
.error-bar .icon {
  margin-top: 3px;
}
.error-jump {
  flex: none;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font-weight: 750;
  text-decoration: underline;
  cursor: pointer;
}
.error-text {
  min-width: 0;
}

@media (min-width: 900px) {
  .workspace {
    height: calc(100dvh - 57px);
    flex: none;
  }
  .panes {
    display: grid;
    grid-template-columns: minmax(340px, 5fr) 7fr;
    align-items: stretch;
  }
  .pane-view {
    order: 2;
    height: auto;
  }
  .pane-code {
    order: 1;
    min-height: 0;
  }
  main {
    min-height: 0;
  }
}

@media (max-width: 760px) {
  .app-header {
    gap: 8px;
    padding: 4px 8px;
  }
  .brand-name {
    font-size: 1.1rem;
  }
  .main-nav a span {
    display: none;
  }
  .main-nav a {
    padding: 8px 10px;
  }
  .toolbar {
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 10px;
    padding: 6px 8px;
    scrollbar-width: thin;
  }
  .toolbar > * {
    flex: none;
  }
  .btn-tool .btn-label {
    display: none;
  }
  .btn-tool {
    padding: 7px 11px;
  }
  .speed-label {
    display: none;
  }
  .panes {
    padding: 8px;
    gap: 8px;
  }
  .pane-view {
    height: clamp(240px, 40vh, 420px);
  }
}

@media (pointer: coarse) {
  .code-input,
  .code-highlight,
  .gutter,
  .measure {
    font-size: 16px !important;
    line-height: 24px !important;
  }
  :root {
    --ed-lh: 24px;
  }
}

/* ───────────── edytor ───────────── */

.editor {
  --ed-lh: 21px;
  --ed-pad: 10px;
  position: relative;
  flex: 1;
  display: flex;
  min-height: 220px;
  background: var(--ed-bg);
  font: 14px/var(--ed-lh) var(--mono);
}
@media (pointer: coarse) {
  .editor {
    --ed-lh: 24px;
    font-size: 16px;
  }
}
.editor:focus-within {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--focus) 70%, transparent);
}

.gutter {
  flex: none;
  position: relative;
  width: calc(var(--gutter-digits, 2) * 1ch + 22px);
  overflow: hidden;
  background: var(--ed-gutter);
  color: var(--ed-gutter-ink);
  text-align: right;
  user-select: none;
  -webkit-user-select: none;
  border-right: 1px solid var(--border);
}
.gutter-inner {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: var(--ed-pad) 10px var(--ed-pad) 0;
  will-change: transform;
}
.gutter-text {
  margin: 0;
  font: inherit;
  line-height: var(--ed-lh);
}
.gutter-active,
.gutter-error {
  position: absolute;
  left: 0;
  right: 0;
}
.gutter-active {
  background: var(--accent);
  opacity: 0.28;
}
.gutter-error {
  background: var(--danger);
  color: #fff;
  font-weight: 800;
  text-align: left;
  padding-left: 5px;
  line-height: var(--ed-lh);
  font-size: 12px;
}

.editor-body {
  position: relative;
  flex: 1;
  min-width: 0;
}
.layers {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.layers-inner {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  will-change: transform;
}
.band {
  position: absolute;
  left: 0;
  width: 100%;
  min-width: 100vw;
}
.band-active {
  background: var(--ed-band);
  box-shadow: inset 3px 0 0 var(--accent);
}
.band-error {
  background: var(--ed-band-error);
}
.code-highlight {
  position: relative;
  margin: 0;
  padding: var(--ed-pad) 14px var(--ed-pad) 12px;
  font: inherit;
  line-height: var(--ed-lh);
  white-space: pre;
  tab-size: 2;
  color: var(--ink);
}
.code-highlight code {
  font: inherit;
}
.code-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: var(--ed-pad) 14px var(--ed-pad) 12px;
  border: 0;
  outline: 0;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: var(--ink);
  font: inherit;
  line-height: var(--ed-lh);
  white-space: pre;
  tab-size: 2;
  letter-spacing: normal;
}
.code-input::selection {
  background: color-mix(in srgb, var(--focus) 35%, transparent);
  -webkit-text-fill-color: transparent;
}
.measure {
  position: absolute;
  visibility: hidden;
  white-space: pre;
  font: inherit;
  pointer-events: none;
}

.t-cmd {
  color: var(--t-cmd);
  font-weight: 650;
}
.t-def {
  color: var(--t-def);
  font-weight: 650;
}
.t-val {
  color: var(--t-num);
  font-weight: 650;
}
.t-num {
  color: var(--t-num);
}
.t-str {
  color: var(--t-str);
}
.t-color {
  border-bottom: 3px solid var(--swatch);
}
.t-com {
  color: var(--t-com);
  font-style: italic;
}
.t-br {
  color: var(--t-br);
  font-weight: 700;
}
.t-op {
  color: var(--t-op);
}
.t-proc {
  color: var(--t-proc);
  font-weight: 650;
}
.t-name {
  color: var(--ink);
}
.t-bad {
  color: var(--danger);
}
.err-mark {
  text-decoration: underline wavy var(--danger);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
  background: color-mix(in srgb, var(--danger) 16%, transparent);
  border-radius: 2px;
}
.err-point {
  position: relative;
  background: none;
  text-decoration: none;
}
.err-point::after {
  content: '';
  position: absolute;
  left: -2px;
  bottom: 0;
  width: 8px;
  height: 4px;
  border-bottom: 2px solid var(--danger);
}

.err-bubble {
  position: absolute;
  z-index: 4;
  max-width: min(560px, calc(100% - 12px));
  padding: 6px 10px;
  border-radius: 8px;
  background: #b3261e;
  color: #fff;
  font: 13px/1.4 var(--sans);
  box-shadow: var(--shadow);
  pointer-events: none;
}
.err-bubble::before {
  content: '';
  position: absolute;
  top: -5px;
  left: calc(var(--arrow-x, 14px) - 5px);
  border: 5px solid transparent;
  border-top: 0;
  border-bottom-color: #b3261e;
}
.err-bubble.above::before {
  top: auto;
  bottom: -5px;
  border-bottom: 0;
  border-top: 5px solid #b3261e;
  border-bottom-color: transparent;
}

/* ───────────── wyzwanie w pracowni ───────────── */

.challenge-host {
  flex: none;
  max-height: 46%;
  overflow: auto;
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}
.challenge-panel {
  padding: 12px 14px 14px;
}
.challenge-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.challenge-head h2 {
  margin: 0 8px 0 0;
  font-size: 1.15rem;
}
.challenge-panel p {
  margin: 8px 0;
}
.challenge-details {
  margin: 4px 0 8px;
  padding-left: 20px;
  color: var(--muted);
  font-size: 0.93rem;
}
.challenge-panel details {
  margin: 6px 0;
}
.challenge-panel summary {
  cursor: pointer;
  font-weight: 650;
  color: var(--accent-text);
}
.challenge-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 10px;
}
.check-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}
.check-label input {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}
.link-quiet {
  font-weight: 600;
}
.challenge-result {
  margin-top: 10px;
}
.challenge-result.pass,
.challenge-result.fail {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px 12px;
  border-radius: 10px;
}
.challenge-result.pass {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.challenge-result.fail {
  background: var(--danger-soft);
  color: var(--danger-ink);
}
.challenge-result p {
  margin: 2px 0 0;
}
.challenge-result .icon {
  margin-top: 2px;
}

/* ───────────── odznaki ───────────── */

.badge {
  display: inline-block;
  padding: 1px 9px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-text);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  vertical-align: middle;
  text-transform: uppercase;
}
.badge-ok {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.level-1 {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.level-2 {
  background: var(--warn-soft);
  color: var(--warn-ink);
}
.level-3 {
  background: var(--danger-soft);
  color: var(--danger-ink);
}

/* ───────────── strony ───────────── */

.page-host {
  flex: 1;
  min-width: 0;
}
.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 16px 72px;
}
.page-head h1 {
  margin: 0 0 6px;
  font-size: clamp(1.7rem, 4vw, 2.3rem);
  letter-spacing: -0.02em;
}
.lead {
  margin: 0 0 24px;
  max-width: 62ch;
  color: var(--muted);
  font-size: 1.05rem;
}
.group-title {
  margin: 28px 0 12px;
  font-size: 1.1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(255px, 1fr));
  gap: 16px;
}
.card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
}
.card-done {
  border-color: color-mix(in srgb, var(--ok-ink) 45%, var(--border));
}
.card .thumb {
  position: relative;
  inset: auto;
  width: 100%;
  height: 180px;
  cursor: default;
  pointer-events: none;
  border-bottom: 1px solid var(--border);
}
.card-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 14px 16px 16px;
}
.card-body h2 {
  margin: 0;
  font-size: 1.1rem;
}
.card-body p {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 0.95rem;
  flex: 1;
}

.progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  font-weight: 650;
}
.progress-bar {
  width: min(280px, 50vw);
  height: 10px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  overflow: hidden;
}
.progress-bar span {
  display: block;
  height: 100%;
  background: var(--accent);
}

/* opis języka */

.ref-layout {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr);
}
@media (min-width: 960px) {
  .ref-layout {
    grid-template-columns: 250px minmax(0, 1fr);
    align-items: start;
  }
  .toc {
    position: sticky;
    top: 70px;
    max-height: calc(100dvh - 90px);
    overflow: auto;
  }
}
.toc {
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
}
.toc-title {
  margin: 0 0 6px;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--muted);
}
.toc ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.toc li a {
  display: block;
  padding: 4px 0;
  text-decoration: none;
}
.toc li a:hover {
  text-decoration: underline;
}
.toc-sub {
  display: block;
  margin-top: 6px;
  font-size: 0.85rem;
  color: var(--muted);
}
.toc-cmds {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
}
.toc-cmds a {
  font-family: var(--mono);
  font-size: 0.9rem;
}

.ref-content {
  min-width: 0;
}
.ref-section {
  margin-bottom: 34px;
  scroll-margin-top: 70px;
}
.ref-section h2 {
  margin: 0 0 10px;
  font-size: 1.45rem;
  letter-spacing: -0.01em;
}
.ref-section p,
.ref-section li {
  max-width: 78ch;
}
.command {
  margin: 14px 0;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  scroll-margin-top: 70px;
}
.command header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.command h3 {
  margin: 0;
  font-size: 1.05rem;
}
.command h3 code {
  font-family: var(--mono);
  color: var(--accent-text);
}
.command p {
  margin: 6px 0;
}
.aliases {
  color: var(--muted);
  font-size: 0.92rem;
}
code.inline-code,
.ref-section p code,
.ref-section li code,
.ref-section td code {
  padding: 1px 6px;
  border-radius: 6px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  font: 0.88em var(--mono);
}
.note {
  padding: 10px 14px;
  border-left: 4px solid var(--copper);
  background: var(--surface-2);
  border-radius: 0 10px 10px 0;
}

.sample {
  margin: 10px 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: var(--ed-bg);
}
.code-sample {
  margin: 0;
  padding: 10px 14px;
  overflow-x: auto;
  font: 13.5px/1.55 var(--mono);
  white-space: pre;
  tab-size: 2;
  color: var(--ink);
}
.sample-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  background: var(--ed-gutter);
  border-top: 1px solid var(--border);
}

.table-wrap {
  overflow-x: auto;
  margin: 10px 0;
}
table {
  width: 100%;
  border-collapse: collapse;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: 0.95rem;
}
th,
td {
  padding: 8px 12px;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--border);
}
th {
  background: var(--surface-2);
  font-weight: 700;
}
tr:last-child td {
  border-bottom: 0;
}
kbd {
  display: inline-block;
  min-width: 1.7em;
  padding: 1px 7px;
  border: 1px solid var(--border);
  border-bottom-width: 3px;
  border-radius: 6px;
  background: var(--surface-2);
  font: 600 0.85em var(--mono);
  text-align: center;
}
.keys {
  white-space: nowrap;
}

/* ───────────── okna i powiadomienia ───────────── */

.dialog {
  width: min(520px, calc(100vw - 24px));
  padding: 20px 22px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}
.dialog-wide {
  width: min(680px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(8, 16, 13, 0.6);
}
.dialog-title {
  margin: 0 0 10px;
  font-size: 1.25rem;
}
.dialog-body p {
  margin: 8px 0;
}
.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}
.share-input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-2);
  font: 13px var(--mono);
}
.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.history-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 10px;
}
.history-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  font-size: 0.9rem;
}
.history-meta code {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-family: var(--mono);
}

.toasts {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(560px, calc(100vw - 24px));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 16px;
  border-radius: 12px;
  background: #1d2a26;
  color: #f0f5f2;
  box-shadow: var(--shadow);
  pointer-events: auto;
  animation: toast-in 0.2s ease-out;
}
.toast span {
  flex: 1;
}
.toast .btn {
  color: #9be6cd;
  border-color: #9be6cd55;
}
.toast .btn:hover:not(:disabled) {
  background: #ffffff18;
}
.toast .toast-close {
  color: #f0f5f2;
  width: 32px;
  height: 32px;
}
.toast .toast-close:hover {
  background: #ffffff22;
}
.toast-error {
  background: #7d1a14;
}
.toast-success {
  background: #11513b;
}
.toast.leaving {
  opacity: 0;
  transition: opacity 0.2s;
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

tool_use_result.content:
/* ───────────── motywy ───────────── */

:root {
  color-scheme: light;
  --bg: #f4efe4;
  --surface: #fffdf8;
  --surface-2: #f7f1e4;
  --ink: #1d2a26;
  --muted: #5b6a64;
  --border: #ddd4c1;
  --accent: #0f7a5d;
  --accent-strong: #0b5f48;
  --accent-ink: #ffffff;
  --accent-soft: #dcefe7;
  --accent-text: #0b6b52;
  --copper: #b8672a;
  --danger: #b3261e;
  --danger-soft: #fbe6e3;
  --danger-ink: #7d1a14;
  --ok-soft: #d8f0e1;
  --ok-ink: #14663a;
  --warn-soft: #fbecc9;
  --warn-ink: #77520a;
  --focus: #1769c2;
  --shadow: 0 6px 24px rgba(40, 32, 12, 0.14);

  /* płótno – papier jest jasny w obu motywach, żeby kolory programów były czytelne */
  --paper: #fbf8f0;
  --grid-minor: #eee8d8;
  --grid-major: #ded5bf;
  --axis: #a1987f;
  --canvas-label: #7d755f;
  --ghost: #6f8191;
  --axis-x: #c4483b;
  --axis-y: #2e9e5b;
  --axis-z: #2b6fb3;

  /* edytor */
  --ed-bg: #fffdf8;
  --ed-gutter: #f3ecdc;
  --ed-gutter-ink: #8f8670;
  --ed-band: rgba(15, 122, 93, 0.13);
  --ed-band-error: rgba(179, 38, 30, 0.1);
  --t-cmd: #0b6b52;
  --t-def: #86379c;
  --t-num: #a8480f;
  --t-str: #6d41a0;
  --t-com: #766f5c;
  --t-br: #b03a2e;
  --t-proc: #1c5ca8;
  --t-op: #5b6a64;

  --mono: ui-monospace, 'SF Mono', 'Cascadia Code', 'JetBrains Mono', Menlo, Consolas, 'Liberation Mono', monospace;
  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #0f1715;
  --surface: #16211e;
  --surface-2: #1b2a26;
  --ink: #e6eee9;
  --muted: #9bb0a7;
  --border: #2b3d37;
  --accent: #36bd93;
  --accent-strong: #52d1a9;
  --accent-ink: #04211a;
  --accent-soft: #1d3a31;
  --accent-text: #5fd8b3;
  --copper: #e0996a;
  --danger: #ff8f85;
  --danger-soft: #3a1c1a;
  --danger-ink: #ffc9c3;
  --ok-soft: #173a29;
  --ok-ink: #8fe0b2;
  --warn-soft: #3b3010;
  --warn-ink: #f2d27c;
  --focus: #7ab8ff;
  --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);

  --paper: #ebe6d8;
  --grid-minor: #e1dbc9;
  --grid-major: #d1c9b3;
  --axis: #8c836b;
  --canvas-label: #6d654f;
  --ghost: #5f7384;
  --axis-x: #b83d30;
  --axis-y: #25894d;
  --axis-z: #2461a3;

  --ed-bg: #121c19;
  --ed-gutter: #172420;
  --ed-gutter-ink: #70877d;
  --ed-band: rgba(54, 189, 147, 0.16);
  --ed-band-error: rgba(255, 143, 133, 0.14);
  --t-cmd: #5fd8b3;
  --t-def: #d9a0ee;
  --t-num: #f0a46b;
  --t-str: #c4a0ee;
  --t-com: #7f948b;
  --t-br: #ff9a8f;
  --t-proc: #8fb8f5;
  --t-op: #9bb0a7;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --bg: #0f1715;
    --surface: #16211e;
    --surface-2: #1b2a26;
    --ink: #e6eee9;
    --muted: #9bb0a7;
    --border: #2b3d37;
    --accent: #36bd93;
    --accent-strong: #52d1a9;
    --accent-ink: #04211a;
    --accent-soft: #1d3a31;
    --accent-text: #5fd8b3;
    --copper: #e0996a;
    --danger: #ff8f85;
    --danger-soft: #3a1c1a;
    --danger-ink: #ffc9c3;
    --ok-soft: #173a29;
    --ok-ink: #8fe0b2;
    --warn-soft: #3b3010;
    --warn-ink: #f2d27c;
    --focus: #7ab8ff;
    --shadow: 0 6px 24px rgba(0, 0, 0, 0.5);
    --paper: #ebe6d8;
    --grid-minor: #e1dbc9;
    --grid-major: #d1c9b3;
    --axis: #8c836b;
    --canvas-label: #6d654f;
    --ghost: #5f7384;
    --axis-x: #b83d30;
    --axis-y: #25894d;
    --axis-z: #2461a3;
    --ed-bg: #121c19;
    --ed-gutter: #172420;
    --ed-gutter-ink: #70877d;
    --ed-band: rgba(54, 189, 147, 0.16);
    --ed-band-error: rgba(255, 143, 133, 0.14);
    --t-cmd: #5fd8b3;
    --t-def: #d9a0ee;
    --t-num: #f0a46b;
    --t-str: #c4a0ee;
    --t-com: #7f948b;
    --t-br: #ff9a8f;
    --t-proc: #8fb8f5;
    --t-op: #9bb0a7;
  }
}

/* ───────────── podstawy ───────────── */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  height: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100%;
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--ink);
}

#app {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  margin: -1px;
  padding: 0;
  border: 0;
}

[hidden] {
  display: none !important;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -60px;
  z-index: 100;
  padding: 10px 16px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  font-weight: 700;
  text-decoration: none;
}
.skip-link:focus {
  top: 8px;
}

a {
  color: var(--accent-text);
}

.muted {
  color: var(--muted);
}

/* ───────────── nagłówek ───────────── */

.app-header {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px 20px;
  min-height: 56px;
  padding: 6px 16px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  text-decoration: none;
  font-weight: 800;
  font-size: 1.3rem;
  letter-spacing: -0.01em;
}
.brand-name {
  background: linear-gradient(100deg, var(--accent-text), var(--copper));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.logo-mark {
  flex: none;
}

.main-nav {
  display: flex;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
.main-nav a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px;
  border-radius: 10px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 600;
  min-height: 40px;
}
.main-nav a:hover {
  background: var(--surface-2);
  color: var(--ink);
}
.main-nav a[aria-current='page'] {
  background: var(--accent-soft);
  color: var(--accent-text);
}

.header-actions {
  display: flex;
  gap: 6px;
  margin-left: auto;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--border);
}

.icon {
  flex: none;
}

/* ───────────── przyciski ───────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font-weight: 650;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
}
.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: color-mix(in srgb, var(--border) 60%, var(--ink));
}
.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}
.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn-small {
  min-height: 34px;
  padding: 4px 11px;
  font-size: 0.9rem;
}
.btn-ghost {
  background: transparent;
}

/* ───────────── pracownia ───────────── */

main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
main:focus {
  outline: none;
}

.workspace {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.toolbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  padding: 8px 12px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.tool-group {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.seg {
  display: inline-flex;
  margin: 0;
  padding: 2px;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface-2);
}
.seg-item {
  position: relative;
  display: block;
}
.seg-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
}
.seg-item span {
  display: block;
  min-width: 52px;
  padding: 6px 14px;
  border-radius: 9px;
  text-align: center;
  font-weight: 750;
  letter-spacing: 0.02em;
  color: var(--muted);
}
.seg-input:checked + span {
  background: var(--accent);
  color: var(--accent-ink);
}
.seg-input:focus-visible + span {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.seg-input:disabled {
  cursor: not-allowed;
}
.seg-input:disabled:not(:checked) + span {
  opacity: 0.5;
}

.speed {
  gap: 8px;
}
.speed-label {
  font-size: 0.85rem;
  color: var(--muted);
  font-weight: 600;
}
.speed input[type='range'] {
  width: 120px;
  accent-color: var(--accent);
}
.speed-out {
  min-width: 7.5em;
  font-size: 0.85rem;
  color: var(--ink);
}

.select {
  height: 40px;
  padding: 0 32px 0 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  max-width: 190px;
  font-weight: 600;
  cursor: pointer;
}
.select:disabled {
  opacity: 0.5;
}
.select-wrap {
  display: flex;
}

.tool-files .btn-label {
  display: none;
}
.tool-files .btn {
  padding: 7px 10px;
}
.btn-tool .btn-label {
  display: inline;
}

.panes {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
  min-height: 0;
}

.pane {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
}

.pane-view {
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--paper);
  height: clamp(280px, 46vh, 520px);
  flex: none;
}

.view-host {
  position: relative;
  flex: 1;
  min-height: 0;
}

.view {
  position: absolute;
  inset: 0;
  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}
.view.dragging {
  cursor: grabbing;
}
.view:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.view canvas {
  display: block;
}

.view-controls {
  position: absolute;
  top: 10px;
  right: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.view-btn {
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  border-color: var(--border);
  backdrop-filter: blur(4px);
}

.view-info {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--surface);
  border-top: 1px solid var(--border);
  color: var(--muted);
  font: 12.5px/1.4 var(--mono);
  white-space: nowrap;
  overflow: hidden;
}
.info-swatch {
  flex: none;
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(0, 0, 0, 0.35);
}
.info-text {
  overflow: hidden;
  text-overflow: ellipsis;
}

.pane-code {
  display: flex;
  flex-direction: column;
  background: var(--ed-bg);
  min-height: 360px;
}

.status {
  flex: none;
  padding: 7px 14px;
  border-top: 1px solid var(--border);
  background: var(--surface);
  color: var(--muted);
  font-size: 0.88rem;
}

.error-bar {
  flex: none;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 14px;
  background: var(--danger-soft);
  color: var(--danger-ink);
  border-top: 1px solid color-mix(in srgb, var(--danger) 35%, transparent);
  font-size: 0.92rem;
}
.error-bar .icon {
  margin-top: 3px;
}
.error-jump {
  flex: none;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font-weight: 750;
  text-decoration: underline;
  cursor: pointer;
}
.error-text {
  min-width: 0;
}

@media (min-width: 900px) {
  .workspace {
    height: calc(100dvh - 57px);
    flex: none;
  }
  .panes {
    display: grid;
    grid-template-columns: minmax(340px, 5fr) 7fr;
    align-items: stretch;
  }
  .pane-view {
    order: 2;
    height: auto;
  }
  .pane-code {
    order: 1;
    min-height: 0;
  }
  main {
    min-height: 0;
  }
}

@media (max-width: 760px) {
  .app-header {
    gap: 8px;
    padding: 4px 8px;
  }
  .brand-name {
    font-size: 1.1rem;
  }
  .main-nav a span {
    display: none;
  }
  .main-nav a {
    padding: 8px 10px;
  }
  .toolbar {
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 10px;
    padding: 6px 8px;
    scrollbar-width: thin;
  }
  .toolbar > * {
    flex: none;
  }
  .btn-tool .btn-label {
    display: none;
  }
  .btn-tool {
    padding: 7px 11px;
  }
  .speed-label {
    display: none;
  }
  .panes {
    padding: 8px;
    gap: 8px;
  }
  .pane-view {
    height: clamp(240px, 40vh, 420px);
  }
}

@media (pointer: coarse) {
  .code-input,
  .code-highlight,
  .gutter,
  .measure {
    font-size: 16px !important;
    line-height: 24px !important;
  }
  :root {
    --ed-lh: 24px;
  }
}

/* ───────────── edytor ───────────── */

.editor {
  --ed-lh: 21px;
  --ed-pad: 10px;
  position: relative;
  flex: 1;
  display: flex;
  min-height: 220px;
  background: var(--ed-bg);
  font: 14px/var(--ed-lh) var(--mono);
}
@media (pointer: coarse) {
  .editor {
    --ed-lh: 24px;
    font-size: 16px;
  }
}
.editor:focus-within {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--focus) 70%, transparent);
}

.gutter {
  flex: none;
  position: relative;
  width: calc(var(--gutter-digits, 2) * 1ch + 22px);
  overflow: hidden;
  background: var(--ed-gutter);
  color: var(--ed-gutter-ink);
  text-align: right;
  user-select: none;
  -webkit-user-select: none;
  border-right: 1px solid var(--border);
}
.gutter-inner {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  padding: var(--ed-pad) 10px var(--ed-pad) 0;
  will-change: transform;
}
.gutter-text {
  margin: 0;
  font: inherit;
  line-height: var(--ed-lh);
}
.gutter-active,
.gutter-error {
  position: absolute;
  left: 0;
  right: 0;
}
.gutter-active {
  background: var(--accent);
  opacity: 0.28;
}
.gutter-error {
  background: var(--danger);
  color: #fff;
  font-weight: 800;
  text-align: left;
  padding-left: 5px;
  line-height: var(--ed-lh);
  font-size: 12px;
}

.editor-body {
  position: relative;
  flex: 1;
  min-width: 0;
}
.layers {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.layers-inner {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  will-change: transform;
}
.band {
  position: absolute;
  left: 0;
  width: 100%;
  min-width: 100vw;
}
.band-active {
  background: var(--ed-band);
  box-shadow: inset 3px 0 0 var(--accent);
}
.band-error {
  background: var(--ed-band-error);
}
.code-highlight {
  position: relative;
  margin: 0;
  padding: var(--ed-pad) 14px var(--ed-pad) 12px;
  font: inherit;
  line-height: var(--ed-lh);
  white-space: pre;
  tab-size: 2;
  color: var(--ink);
}
.code-highlight code {
  font: inherit;
}
.code-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: var(--ed-pad) 14px var(--ed-pad) 12px;
  border: 0;
  outline: 0;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: var(--ink);
  font: inherit;
  line-height: var(--ed-lh);
  white-space: pre;
  tab-size: 2;
  letter-spacing: normal;
}
.code-input::selection {
  background: color-mix(in srgb, var(--focus) 35%, transparent);
  -webkit-text-fill-color: transparent;
}
.measure {
  position: absolute;
  visibility: hidden;
  white-space: pre;
  font: inherit;
  pointer-events: none;
}

.t-cmd {
  color: var(--t-cmd);
  font-weight: 650;
}
.t-def {
  color: var(--t-def);
  font-weight: 650;
}
.t-val {
  color: var(--t-num);
  font-weight: 650;
}
.t-num {
  color: var(--t-num);
}
.t-str {
  color: var(--t-str);
}
.t-color {
  border-bottom: 3px solid var(--swatch);
}
.t-com {
  color: var(--t-com);
  font-style: italic;
}
.t-br {
  color: var(--t-br);
  font-weight: 700;
}
.t-op {
  color: var(--t-op);
}
.t-proc {
  color: var(--t-proc);
  font-weight: 650;
}
.t-name {
  color: var(--ink);
}
.t-bad {
  color: var(--danger);
}
.err-mark {
  text-decoration: underline wavy var(--danger);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
  background: color-mix(in srgb, var(--danger) 16%, transparent);
  border-radius: 2px;
}
.err-point {
  position: relative;
  background: none;
  text-decoration: none;
}
.err-point::after {
  content: '';
  position: absolute;
  left: -2px;
  bottom: 0;
  width: 8px;
  height: 4px;
  border-bottom: 2px solid var(--danger);
}

.err-bubble {
  position: absolute;
  z-index: 4;
  max-width: min(560px, calc(100% - 12px));
  padding: 6px 10px;
  border-radius: 8px;
  background: #b3261e;
  color: #fff;
  font: 13px/1.4 var(--sans);
  box-shadow: var(--shadow);
  pointer-events: none;
}
.err-bubble::before {
  content: '';
  position: absolute;
  top: -5px;
  left: calc(var(--arrow-x, 14px) - 5px);
  border: 5px solid transparent;
  border-top: 0;
  border-bottom-color: #b3261e;
}
.err-bubble.above::before {
  top: auto;
  bottom: -5px;
  border-bottom: 0;
  border-top: 5px solid #b3261e;
  border-bottom-color: transparent;
}

/* ───────────── wyzwanie w pracowni ───────────── */

.challenge-host {
  flex: none;
  max-height: 46%;
  overflow: auto;
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}
.challenge-panel {
  padding: 12px 14px 14px;
}
.challenge-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.challenge-head h2 {
  margin: 0 8px 0 0;
  font-size: 1.15rem;
}
.challenge-panel p {
  margin: 8px 0;
}
.challenge-details {
  margin: 4px 0 8px;
  padding-left: 20px;
  color: var(--muted);
  font-size: 0.93rem;
}
.challenge-panel details {
  margin: 6px 0;
}
.challenge-panel summary {
  cursor: pointer;
  font-weight: 650;
  color: var(--accent-text);
}
.challenge-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 10px;
}
.check-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}
.check-label input {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}
.link-quiet {
  font-weight: 600;
}
.challenge-result {
  margin-top: 10px;
}
.challenge-result.pass,
.challenge-result.fail {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px 12px;
  border-radius: 10px;
}
.challenge-result.pass {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.challenge-result.fail {
  background: var(--danger-soft);
  color: var(--danger-ink);
}
.challenge-result p {
  margin: 2px 0 0;
}
.challenge-result .icon {
  margin-top: 2px;
}

/* ───────────── odznaki ───────────── */

.badge {
  display: inline-block;
  padding: 1px 9px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-text);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  vertical-align: middle;
  text-transform: uppercase;
}
.badge-ok {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.level-1 {
  background: var(--ok-soft);
  color: var(--ok-ink);
}
.level-2 {
  background: var(--warn-soft);
  color: var(--warn-ink);
}
.level-3 {
  background: var(--danger-soft);
  color: var(--danger-ink);
}

/* ───────────── strony ───────────── */

.page-host {
  flex: 1;
  min-width: 0;
}
.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 16px 72px;
}
.page-head h1 {
  margin: 0 0 6px;
  font-size: clamp(1.7rem, 4vw, 2.3rem);
  letter-spacing: -0.02em;
}
.lead {
  margin: 0 0 24px;
  max-width: 62ch;
  color: var(--muted);
  font-size: 1.05rem;
}
.group-title {
  margin: 28px 0 12px;
  font-size: 1.1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(255px, 1fr));
  gap: 16px;
}
.card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
}
.card-done {
  border-color: color-mix(in srgb, var(--ok-ink) 45%, var(--border));
}
.card .thumb {
  position: relative;
  inset: auto;
  width: 100%;
  height: 180px;
  cursor: default;
  pointer-events: none;
  border-bottom: 1px solid var(--border);
