.card-body h2 {
  margin: 0;
  font-size: 1.1rem;
}
.card-body p {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 0.95rem;
  flex: 1;
}

.progress {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  font-weight: 650;
}
.progress-bar {
  width: min(280px, 50vw);
  height: 10px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  overflow: hidden;
}
.progress-bar span {
  display: block;
  height: 100%;
  background: var(--accent);
}

/* opis języka */

.ref-layout {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr);
}
@media (min-width: 960px) {
  .ref-layout {
    grid-template-columns: 250px minmax(0, 1fr);
    align-items: start;
  }
  .toc {
    position: sticky;
    top: 70px;
    max-height: calc(100dvh - 90px);
    overflow: auto;
  }
}
.toc {
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
}
.toc-title {
  margin: 0 0 6px;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--muted);
}
.toc ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.toc li a {
  display: block;
  padding: 4px 0;
  text-decoration: none;
}
.toc li a:hover {
  text-decoration: underline;
}
.toc-sub {
  display: block;
  margin-top: 6px;
  font-size: 0.85rem;
  color: var(--muted);
}
.toc-cmds {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
}
.toc-cmds a {
  font-family: var(--mono);
  font-size: 0.9rem;
}

.ref-content {
  min-width: 0;
}
.ref-section {
  margin-bottom: 34px;
  scroll-margin-top: 70px;
}
.ref-section h2 {
  margin: 0 0 10px;
  font-size: 1.45rem;
  letter-spacing: -0.01em;
}
.ref-section p,
.ref-section li {
  max-width: 78ch;
}
.command {
  margin: 14px 0;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  scroll-margin-top: 70px;
}
.command header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.command h3 {
  margin: 0;
  font-size: 1.05rem;
}
.command h3 code {
  font-family: var(--mono);
  color: var(--accent-text);
}
.command p {
  margin: 6px 0;
}
.aliases {
  color: var(--muted);
  font-size: 0.92rem;
}
code.inline-code,
.ref-section p code,
.ref-section li code,
.ref-section td code {
  padding: 1px 6px;
  border-radius: 6px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  font: 0.88em var(--mono);
}
.note {
  padding: 10px 14px;
  border-left: 4px solid var(--copper);
  background: var(--surface-2);
  border-radius: 0 10px 10px 0;
}

.sample {
  margin: 10px 0;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: var(--ed-bg);
}
.code-sample {
  margin: 0;
  padding: 10px 14px;
  overflow-x: auto;
  font: 13.5px/1.55 var(--mono);
  white-space: pre;
  tab-size: 2;
  color: var(--ink);
}
.sample-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  background: var(--ed-gutter);
  border-top: 1px solid var(--border);
}

.table-wrap {
  overflow-x: auto;
  margin: 10px 0;
}
table {
  width: 100%;
  border-collapse: collapse;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: 0.95rem;
}
th,
td {
  padding: 8px 12px;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--border);
}
th {
  background: var(--surface-2);
  font-weight: 700;
}
tr:last-child td {
  border-bottom: 0;
}
kbd {
  display: inline-block;
  min-width: 1.7em;
  padding: 1px 7px;
  border: 1px solid var(--border);
  border-bottom-width: 3px;
  border-radius: 6px;
  background: var(--surface-2);
  font: 600 0.85em var(--mono);
  text-align: center;
}
.keys {
  white-space: nowrap;
}

/* ───────────── okna i powiadomienia ───────────── */

.dialog {
  width: min(520px, calc(100vw - 24px));
  padding: 20px 22px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}
.dialog-wide {
  width: min(680px, calc(100vw - 24px));
}
.dialog::backdrop {
  background: rgba(8, 16, 13, 0.6);
}
.dialog-title {
  margin: 0 0 10px;
  font-size: 1.25rem;
}
.dialog-body p {
  margin: 8px 0;
}
.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}
.share-input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-2);
  font: 13px var(--mono);
}
.history-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.history-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 10px;
}
.history-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  font-size: 0.9rem;
}
.history-meta code {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-family: var(--mono);
}

.toasts {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(560px, calc(100vw - 24px));
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 10px 10px 16px;
  border-radius: 12px;
  background: #1d2a26;
  color: #f0f5f2;
  box-shadow: var(--shadow);
  pointer-events: auto;
  animation: toast-in 0.2s ease-out;
}
.toast span {
  flex: 1;
}
.toast .btn {
  color: #9be6cd;
  border-color: #9be6cd55;
}
.toast .btn:hover:not(:disabled) {
  background: #ffffff18;
}
.toast .toast-close {
  color: #f0f5f2;
  width: 32px;
  height: 32px;
}
.toast .toast-close:hover {
  background: #ffffff22;
}
.toast-error {
  background: #7d1a14;
}
.toast-success {
  background: #11513b;
}
.toast.leaving {
  opacity: 0;
  transition: opacity 0.2s;
}
@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

