cat > /tmp/pw5.mjs <<'EOF'
import { chromium } from '/tmp/probe/node_modules/playwright/index.mjs';
import fs from 'node:fs';
const b = await chromium.launch();
const logs=[]; const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
const ctx = await b.newContext({ viewport: { width: 1360, height: 820 }, acceptDownloads: true, permissions: ['clipboard-read','clipboard-write'] });
const p = await ctx.newPage();
p.on('console', m => logs.push(m.type()+': '+m.text())); p.on('pageerror', e => logs.push('PAGEERROR '+e.message));
const BASE='http://localhost:4173/';
await p.goto(BASE); await p.waitForTimeout(300);
// hook
const run = await p.evaluate(() => window.logomocja.run('powtorz 4 [np 100 pw 90]','2d'));
ok(run.segments.length===4 && run.error===null, 'hook run');
ok(typeof await p.evaluate(()=>window.logomocja.version)==='string','version');
// keyboard shortcuts
await p.fill('textarea.code-input','np 100\npw 90\nnp 50');
await p.press('textarea.code-input','Control+Enter');
await p.waitForTimeout(300);
ok((await p.textContent('[data-testid=status]')).includes('Zakończono: 2 odcinki'),'ctrl+enter run: '+await p.textContent('[data-testid=status]'));
await p.evaluate(() => { const s = document.querySelector('#speed'); s.value = '1'; s.dispatchEvent(new Event('input', {bubbles:true})); });
await p.press('textarea.code-input','Control+Enter');
await p.waitForTimeout(100);
await p.keyboard.press('F8');
ok((await p.textContent('[data-testid=status]')).includes('Wstrzymano'),'F8 pause: '+await p.textContent('[data-testid=status]'));
await p.keyboard.press('F10');
await p.keyboard.press('F10');
console.log(await p.textContent('[data-testid=status]'));
await p.keyboard.press('Escape');
ok((await p.textContent('[data-testid=status]')).startsWith('Gotowy'),'Esc reset: '+await p.textContent('[data-testid=status]'));
// edit while running
await p.evaluate(() => { const s = document.querySelector('#speed'); s.value = '0'; s.dispatchEvent(new Event('input', {bubbles:true})); });
await p.click('[data-testid=run]'); await p.waitForTimeout(100);
await p.focus('textarea.code-input'); await p.keyboard.type('x');
await p.waitForTimeout(100);
ok((await p.textContent('[data-testid=status]')).includes('Przerwano'),'edit interrupts: '+await p.textContent('[data-testid=status]'));
// back to instant
await p.evaluate(() => { const s = document.querySelector('#speed'); s.value = '6'; s.dispatchEvent(new Event('input', {bubbles:true})); });
// persistence of drafts + mode
await p.fill('textarea.code-input','; moj szkic 2d\nnp 77');
await p.click('[data-testid=mode-3d] + span'); await p.waitForTimeout(200);
ok((await p.inputValue('textarea.code-input')).includes('Żółw wspina'),'3d draft default loaded');
await p.fill('textarea.code-input','; moj szkic 3d\ngora 90 np 33');
await p.waitForTimeout(500);
await p.reload(); await p.waitForTimeout(500);
ok((await p.inputValue('textarea.code-input')).includes('moj szkic 3d'),'reload keeps 3d draft+mode');
await p.click('[data-testid=mode-2d] + span'); await p.waitForTimeout(200);
ok((await p.inputValue('textarea.code-input')).includes('moj szkic 2d'),'2d draft kept');
// example dialog (dirty draft)
await p.selectOption('[data-testid=example-select]','gwiazda'); await p.waitForTimeout(200);
const dlg = await p.$('dialog[open]');
ok(!!dlg,'confirm dialog on dirty draft');
await p.screenshot({path:'/tmp/shots/confirm.png'});
await p.click('dialog[open] .btn-primary'); await p.waitForTimeout(300);
ok((await p.inputValue('textarea.code-input')).includes('Sekret gwiazdy'),'example loaded');
// history restore
await p.click('[data-testid=history]'); await p.waitForTimeout(200);
await p.screenshot({path:'/tmp/shots/history.png'});
await p.click('dialog[open] li button'); await p.waitForTimeout(300);
ok((await p.inputValue('textarea.code-input')).includes('moj szkic 2d'),'history restore');
// download
const [dl] = await Promise.all([p.waitForEvent('download'), p.click('[data-testid=download]')]);
const path = await dl.path(); ok(fs.readFileSync(path,'utf8').includes('moj szkic 2d') && dl.suggestedFilename().endsWith('.logo'),'download .logo '+dl.suggestedFilename());
// png
const [dl2] = await Promise.all([p.waitForEvent('download'), p.click('[data-testid=png]')]);
