const vocab = ['np','ws','pw','lw','pod','opu','kolor','grubosc','powtorz','niech','jeśli','jeżeli','stop','dom','czyść','gora','pp','nrpowt','oto','już','ma:',',','[',']','(',')','+','-','*','/','<','>','=','<=','<>','1','2','10','0','.5','x','y','f','g',':x','"#16866a"','"#zz"','\n','\n','  ','; c\n','12e','kwadrat','end','to','repcount','"'];
