let internal = 0, okc = 0, errc = 0;
for (let i = 0; i < 40000; i++) {
  const n = 1 + Math.floor(rnd() * 14);
  let s = '';
  for (let k = 0; k < n; k++) s += vocab[Math.floor(rnd() * vocab.length)] + (rnd() < 0.8 ? ' ' : '');
