 55	  return tok.kind === 'eof' ? 'koniec programu' : `„${tok.text}”`;
 56	}
 57	
 58	function errAt(tok: { line: number; col: number }, message: string): LogoError {
 59	  return new LogoError(message, tok.line, tok.col);
 60	}
 61	
 62	/** Miejsce tuż za tokenem (np. gdzie powinien być brakujący element w wierszu). */
 63	function after(tok: Token): { line: number; col: number } {
 64	  return { line: tok.line, col: tok.col + tok.text.length };
 65	}
 66	
 67	export function parse(source: string, mode: Mode): Program {
 68	  if (source.length > MAX_SOURCE_CHARS) {
 69	    throw new LogoError(
 70	      `Program jest za długi: ${source.length} znaków (limit to ${MAX_SOURCE_CHARS})`,
 71	      1,
 72	      1,
 73	    );
 74	  }
 75	  return new Parser(tokenize(source), mode).parseProgram();
 76	}
 77	
 78	class Parser {
 79	  private pos = 0;
 80	  private headers = new Map<string, Header | LogoError>();
 81	  private procs = new Map<string, ProcDef>();
 82	  private topVars = new Set<string>();
 83	  private refs: Ref[] = [];
 84	  private parenDepth = 0;
 85	
 86	  constructor(
 87	    private toks: Token[],
 88	    private mode: Mode,
 89	  ) {}
 90	
 91	  // ───────────────────────── pomocnicze ─────────────────────────
 92	
 93	  private peek(): Token {
 94	    return this.toks[this.pos];
 95	  }
 96	  private next(): Token {
 97	    const t = this.toks[this.pos];
 98	    if (t.kind !== 'eof') this.pos++;
 99	    return t;
100	  }
101	
102	  private checkLexError(t: Token): void {
103	    if (t.kind === 'error') throw errAt(t, t.message ?? 'Błąd składni');
104	  }
105	
106	  // ───────────────────────── nagłówki procedur ─────────────────────────
107	
108	  private scanHeaders(): void {
109	    for (let i = 0; i < this.toks.length; i++) {
110	      const t = this.toks[i];
111	      if (t.kind !== 'ident' || !isDefOpen(t.value as string) || !t.firstOnLine) continue;
112	      try {
113	        const h = this.parseHeader(i);
114	        const name = h.nameTok.value as string;
115	        if (!this.headers.has(name)) this.headers.set(name, h);
116	        i = h.end - 1;
117	      } catch (e) {
118	        if (!(e instanceof LogoError)) throw e;
119	        const nameTok = this.toks[i + 1];
120	        if (nameTok && nameTok.kind === 'ident' && nameTok.line === t.line) {
121	          const name = nameTok.value as string;
122	          if (!this.headers.has(name)) this.headers.set(name, e);
123	        }
124	      }
125	    }
126	  }
127	
128	  private parseHeader(idx: number): Header {
129	    const toks = this.toks;
130	    const oto = toks[idx];
131	    const nameTok = toks[idx + 1];
132	    if (nameTok.kind === 'error') throw errAt(nameTok, nameTok.message ?? 'Błąd składni');
133	    if (nameTok.kind !== 'ident' || nameTok.line !== oto.line) {
134	      throw errAt(
135	        nameTok.kind === 'eof' || nameTok.line !== oto.line ? oto : nameTok,
136	        `Po „${oto.text}” oczekiwano nazwy procedury`,
137	      );
138	    }
139	    const params: Token[] = [];
140	    let i = idx + 2;
141	    const sameLine = (t: Token) => t.kind !== 'eof' && t.line === oto.line;
142	    const t0 = toks[i];
143	    const t1 = toks[i + 1];
144	
145	    const isMa =
146	      sameLine(t0) &&
147	      t0.kind === 'ident' &&
148	      t0.value === 'ma' &&
149	      sameLine(t1) &&
150	      (t1.kind === 'colon' || (t1.kind === 'cname' && t1.start === t0.end));
151	
152	    if (isMa) {
153	      let last: Token = t0;
154	      if (t1.kind === 'colon') {
155	        i += 2;
156	        last = t1;
157	      } else {
158	        i += 1; // dwukropek jest częścią tokenu :nazwa – obsłuży go pętla poniżej
159	        last = t0;
160	      }
161	      for (;;) {
162	        const p = toks[i];
163	        if (!sameLine(p)) {
164	          throw errAt(after(last), 'Po „ma:” oczekiwano nazwy parametru');
165	        }
166	        if (p.kind === 'error') throw errAt(p, p.message ?? 'Błąd składni');
167	        if (p.kind !== 'ident' && p.kind !== 'cname') {
168	          throw errAt(p, `Oczekiwano nazwy parametru, a jest ${q(p)}`);
169	        }
170	        params.push(p);
171	        i++;
172	        last = p;
173	        const sep = toks[i];
174	        if (!sameLine(sep)) break;
175	        if (sep.kind !== 'comma') {
176	          throw errAt(sep, `Parametry oddziela się przecinkami, a jest ${q(sep)}`);
177	        }
178	        last = sep;
179	        i++;
180	      }
181	    } else {
182	      while (sameLine(toks[i])) {
183	        const p = toks[i];
184	        if (p.kind === 'error') throw errAt(p, p.message ?? 'Błąd składni');
185	        if (p.kind !== 'cname') {
186	          throw errAt(
187	            p,
188	            `W nagłówku procedury oczekiwano „ma:” z listą parametrów albo parametrów w postaci :nazwa, a jest ${q(p)}`,
189	          );
190	        }
191	        params.push(p);
192	        i++;
193	      }
194	    }
195	    return { oto, nameTok, params, end: i };
196	  }
197	
198	  // ───────────────────────── program ─────────────────────────
199	
200	  parseProgram(): Program {
201	    this.scanHeaders();
202	    const body: Stmt[] = [];
203	    const ctx: Ctx = { scope: null, repDepth: 0, depth: 0 };
204	    for (;;) {
205	      const t = this.peek();
206	      if (t.kind === 'eof') break;
207	      if (t.kind === 'ident' && isDefOpen(t.value as string)) {
208	        this.parseDefinition();
209	        continue;
210	      }
211	      body.push(this.parseStatement(ctx));
212	    }
213	    this.resolveRefs();
214	    return { procs: this.procs, body };
215	  }
216	
217	  private resolveRefs(): void {
218	    for (const r of this.refs) {
219	      const ok = r.scope
220	        ? r.scope.params.has(r.name) || r.scope.assigned.has(r.name) || this.topVars.has(r.name)
221	        : this.topVars.has(r.name);
222	      if (!ok) {
223	        const isProc = this.headers.has(r.name);
224	        throw errAt(
225	          r.tok,
226	          isProc
227	            ? `„${r.tok.text.replace(/^:/, '')}” jest nazwą procedury, a nie zmienną ani parametrem (czy poprzedniemu poleceniu nie brakuje argumentów?)`
228	            : `Nieznana nazwa „${r.tok.text.replace(/^:/, '')}”: to nie jest parametr ani zmienna (przypisz ją poleceniem niech)`,
229	        );
230	      }
231	    }
232	  }
233	
234	  private checkNewName(tok: Token, what: string): string {
235	    const name = tok.value as string;
236	    if (RESERVED.has(name)) {
237	      throw errAt(tok, `„${tok.text}” jest słowem zastrzeżonym i nie może być ${what}`);
238	    }
239	    return name;
240	  }
241	
242	  private parseDefinition(): void {
243	    const oto = this.peek();
244	    if (!oto.firstOnLine) {
245	      throw errAt(oto, `„${oto.text}” musi stać na początku wiersza`);
246	    }
247	    const h = this.parseHeader(this.pos);
248	    this.pos = h.end;
249	    const name = this.checkNewName(h.nameTok, 'nazwą procedury');
250	    if (this.procs.has(name)) {
251	      throw errAt(h.nameTok, `Procedura „${h.nameTok.text}” jest już zdefiniowana`);
252	    }
253	    const params: string[] = [];
254	    for (const p of h.params) {
255	      const pn = this.checkNewName(p, 'nazwą parametru');
256	      if (params.includes(pn)) {
257	        throw errAt(p, `Parametr „${pn}” występuje w nagłówku więcej niż raz`);
258	      }
259	      params.push(pn);
260	    }
261	    const scope: ProcScope = { name, params: new Set(params), assigned: new Set() };
262	    const def: ProcDef = { name, params, body: [], tok: oto, nameTok: h.nameTok };
263	    // Procedura jest widoczna dla samej siebie (rekurencja) – zarejestrowana z góry.
264	    this.procs.set(name, def);
265	    const ctx: Ctx = { scope, repDepth: 0, depth: 0 };
266	    for (;;) {
267	      const t = this.peek();
268	      if (t.kind === 'eof') {
269	        throw errAt(oto, `Brakuje „już” kończącego procedurę „${h.nameTok.text}”`);
270	      }
271	      if (t.kind === 'ident') {
272	        const w = t.value as string;
273	        if (isDefClose(w)) {
274	          if (!t.firstOnLine || !t.lastOnLine) {
275	            throw errAt(t, `„${t.text}” musi stać samo w osobnym wierszu`);
276	          }
277	          this.next();
278	          return;
279	        }
280	        if (isDefOpen(w)) {
281	          throw errAt(
282	            t,
283	            `Definicja procedury nie może być wewnątrz innej procedury (brakuje „już” dla „${h.nameTok.text}”?)`,
284	          );
285	        }
286	      }
287	      def.body.push(this.parseStatement(ctx));
288	    }
289	  }
290	
291	  // ───────────────────────── instrukcje ─────────────────────────
292	
293	  private parseStatement(ctx: Ctx): Stmt {
294	    const t = this.next();
295	    this.checkLexError(t);
296	    if (t.kind === 'ident') {
297	      const w = t.value as string;
298	      const info = COMMAND_TABLE.get(w);
299	      if (info) return this.parseCommand(t, info.command, ctx);
300	      if (isDefOpen(w)) {
301	        throw errAt(t, 'Definicja procedury jest dozwolona tylko na najwyższym poziomie programu');
302	      }
303	      if (isDefClose(w)) {
304	        throw errAt(t, `„${t.text}” nie kończy żadnej procedury (brakuje „oto”)`);
305	      }
306	      if (isRepcount(w)) {
307	        throw errAt(t, `„${t.text}” jest wartością, a nie poleceniem – użyj jej w wyrażeniu`);
308	      }
309	      const h = this.headers.get(w);
310	      if (h) {
311	        if (h instanceof LogoError) throw h;
312	        return this.parseCall(t, w, h.params.length, ctx);
313	      }
314	      throw errAt(t, `Nieznane polecenie „${t.text}”`);
315	    }
316	    switch (t.kind) {
317	      case 'rbr':
318	        throw errAt(t, 'Nieoczekiwany nawias „]” – nie ma pasującego „[”');
319	      case 'rp':
320	        throw errAt(t, 'Nieoczekiwany nawias „)” – nie ma pasującego „(”');
321	      case 'lbr':
322	        throw errAt(t, 'Nieoczekiwany nawias „[” – nawias kwadratowy musi następować po poleceniu');
323	      case 'eof':
324	        throw errAt(t, 'Nieoczekiwany koniec programu');
325	      default:
326	        throw errAt(
327	          t,
328	          `Nieoczekiwane ${q(t)}: w tym miejscu powinno być polecenie (poprzednie polecenie nie przyjmuje więcej argumentów)`,
329	        );
330	    }
331	  }
332	
333	  private parseCommand(tok: Token, command: string, ctx: Ctx): Stmt {
334	    const info = COMMAND_TABLE.get(tok.value as string)!;
335	    if (info.only3d && this.mode === '2d') {
336	      throw errAt(tok, `Polecenie „${tok.text}” działa tylko w trybie 3D`);
337	    }
338	    switch (command) {
339	      case 'fd':
340	      case 'bk':
341	      case 'rt':
342	      case 'lt':
343	      case 'pitchup':
344	      case 'pitchdown':
345	      case 'rr':
346	      case 'rl': {
347	        const arg = this.parseExpr(tok, ctx);
348	        return { t: 'cmd', op: command, arg, tok };
349	      }
350	      case 'pu':
351	      case 'pd':
352	      case 'stop':
353	      case 'home':
354	      case 'cs':
355	        return { t: 'cmd', op: command, tok };
356	      case 'width': {
357	        const arg = this.parseExpr(tok, ctx);
358	        const v = constantValue(arg);
359	        if (v !== undefined && !(Number.isInteger(v) && v >= 1 && v <= MAX_WIDTH)) {
360	          throw errAt(arg.tok, `Grubość musi być liczbą całkowitą od 1 do ${MAX_WIDTH}`);
361	        }
362	        return { t: 'cmd', op: 'width', arg, tok };
363	      }
364	      case 'color': {
365	        const c = this.next();
366	        this.checkLexError(c);
367	        if (c.kind !== 'str') {
368	          throw errAt(
369	            c.kind === 'eof' ? tok : c,
370	            c.kind === 'eof'
371	              ? `Brakuje koloru po „${tok.text}” (np. „#16866a”)`
372	              : `Po „${tok.text}” oczekiwano koloru w cudzysłowie, np. "#16866a", a jest ${q(c)}`,
373	          );
374	        }
375	        if (!/^#[0-9a-fA-F]{6}$/.test(c.value as string)) {
376	          throw errAt(c, `Niepoprawny kolor ${c.text}: oczekiwano zapisu "#rrggbb" (sześć cyfr szesnastkowych)`);
377	        }
378	        return { t: 'cmd', op: 'color', color: (c.value as string).toLowerCase(), tok };
379	      }
380	      case 'repeat': {
381	        const count = this.parseExpr(tok, ctx);
382	        const v = constantValue(count);
383	        if (v !== undefined && !(Number.isInteger(v) && v >= 0 && v <= MAX_REPEAT)) {
384	          throw errAt(count.tok, `Liczba powtórzeń musi być liczbą całkowitą od 0 do ${MAX_REPEAT}`);
385	        }
386	        const body = this.parseBody(tok, { ...ctx, repDepth: ctx.repDepth + 1 });
387	        return { t: 'repeat', count, body, tok };
388	      }
389	      case 'let': {
390	        const n = this.next();
391	        this.checkLexError(n);
392	        if (n.kind !== 'ident') {
393	          throw errAt(
394	            n.kind === 'eof' ? tok : n,
395	            n.kind === 'eof'
396	              ? `Brakuje nazwy zmiennej po „${tok.text}”`
397	              : `Po „${tok.text}” oczekiwano nazwy zmiennej, a jest ${q(n)}`,
398	          );
399	        }
400	        const name = this.checkNewName(n, 'nazwą zmiennej');
401	        if (this.headers.has(name)) {
402	          throw errAt(n, `„${n.text}” jest nazwą procedury i nie może być nazwą zmiennej`);
403	        }
404	        const value = this.parseExpr(tok, ctx);
405	        if (ctx.scope) ctx.scope.assigned.add(name);
406	        else this.topVars.add(name);
407	        return { t: 'let', name, value, tok, global: !ctx.scope };
408	      }
409	      case 'if':
410	      case 'ifelse': {
411	        const cond = this.parseCondition(tok, ctx);
412	        const inner = ctx;
413	        const then = this.parseBody(tok, inner);
414	        if (command === 'if') return { t: 'if', cond, then, tok };
415	        const els = this.parseBody(tok, inner);
416	        return { t: 'if', cond, then, else: els, tok };
417	      }
418	    }
419	    throw errAt(tok, `Nieobsługiwane polecenie „${tok.text}”`);
420	  }
421	
422	  private parseBody(cmdTok: Token, ctx: Ctx): Stmt[] {
423	    const open = this.next();
424	    this.checkLexError(open);
425	    if (open.kind !== 'lbr') {
426	      throw errAt(
427	        open.kind === 'eof' ? cmdTok : open,
428	        open.kind === 'eof'
429	          ? `Brakuje „[” po poleceniu „${cmdTok.text}”`
430	          : `Oczekiwano „[” rozpoczynającego blok, a jest ${q(open)}`,
431	      );
432	    }
433	    if (ctx.depth + 1 > MAX_BRACKET_DEPTH) {
434	      throw errAt(open, `Przekroczono maksymalne zagnieżdżenie nawiasów (${MAX_BRACKET_DEPTH})`);
435	    }
436	    const inner: Ctx = { ...ctx, depth: ctx.depth + 1 };
437	    const body: Stmt[] = [];
438	    for (;;) {
439	      const t = this.peek();
440	      if (t.kind === 'eof') throw errAt(open, 'Nawias „[” nie został zamknięty – brakuje „]”');
441	      if (t.kind === 'rbr') {
442	        this.next();
443	        return body;
444	      }
445	      if (t.kind === 'ident') {
446	        const w = t.value as string;
447	        if (isDefClose(w)) throw errAt(open, 'Nawias „[” nie został zamknięty – brakuje „]”');
448	        if (isDefOpen(w)) {
449	          throw errAt(t, 'Definicji procedury nie można umieszczać wewnątrz nawiasów [ ]');
450	        }
451	      }
452	      body.push(this.parseStatement(inner));
453	    }
454	  }
455	
456	  private parseCall(tok: Token, name: string, arity: number, ctx: Ctx): Stmt {
457	    const args: Expr[] = [];
458	    for (let i = 0; i < arity; i++) {
459	      const t = this.peek();
460	      if (!this.canStartOperand(t)) {
461	        this.checkLexError(t);
462	        throw errAt(
463	          t.kind === 'eof' ? tok : t,
464	          `Procedura „${tok.text}” oczekuje ${arity} ${pluralArgs(arity)}, a podano ${i}`,
465	        );
466	      }
467	      args.push(this.parseExpr(tok, ctx));
468	    }
469	    return { t: 'call', proc: name, args, tok };
470	  }
471	
472	  // ───────────────────────── wyrażenia ─────────────────────────
473	
474	  private canStartOperand(t: Token): boolean {
475	    switch (t.kind) {
476	      case 'num':
477	      case 'cname':
478	      case 'lp':
479	        return true;
480	      case 'op':
481	        return t.value === '+' || t.value === '-';
482	      case 'ident': {
483	        const w = t.value as string;
484	        return isRepcount(w) || !RESERVED.has(w);
485	      }
486	      default:
487	        return false;
488	    }
489	  }
490	
491	  private parseCondition(cmd: Token, ctx: Ctx): Condition {
492	    const left = this.parseExpr(cmd, ctx);
493	    const c = this.peek();
494	    this.checkLexError(c);
495	    if (c.kind !== 'cmp') {
496	      throw errAt(
497	        c.kind === 'eof' ? cmd : c,
498	        `Oczekiwano operatora porównania (<, >, =, <=, >=, <>), a jest ${q(c)}`,
499	      );
500	    }
501	    this.next();
502	    const right = this.parseExpr(cmd, ctx);
503	    return { left, op: c.value as CmpOp, right };
504	  }
505	
506	  /** Argument polecenia: pełne wyrażenie. `cmd` – token, przy którym zgłaszamy brak argumentu na końcu programu. */
507	  private parseExpr(cmd: Token, ctx: Ctx): Expr {
508	    const first = this.parseTerm(cmd, ctx);
509	    const rest: { op: '+' | '-'; e: Expr }[] = [];
510	    for (;;) {
511	      const t = this.peek();
512	      if (t.kind === 'op' && (t.value === '+' || t.value === '-') && this.isBinary(t)) {
513	        this.next();
514	        rest.push({ op: t.value as '+' | '-', e: this.parseTerm(cmd, ctx, t) });
515	      } else break;
516	    }
517	    return rest.length ? { k: 'sum', first, rest, tok: first.tok } : first;
518	  }
519	
520	  private parseTerm(cmd: Token, ctx: Ctx, afterOp?: Token): Expr {
521	    const first = this.parseUnary(cmd, ctx, afterOp);
522	    const rest: { op: '*' | '/'; e: Expr }[] = [];
523	    for (;;) {
524	      const t = this.peek();
525	      if (t.kind === 'op' && (t.value === '*' || t.value === '/') && this.isBinary(t)) {
526	        this.next();
527	        rest.push({ op: t.value as '*' | '/', e: this.parseUnary(cmd, ctx, t) });
528	      } else break;
529	    }
530	    return rest.length ? { k: 'prod', first, rest, tok: first.tok } : first;
531	  }
532	
533	  /** Operator dwuargumentowy musi mieć odstępy po obu stronach albo po żadnej. */
534	  private isBinary(t: Token): boolean {
535	    return t.spaceBefore === t.spaceAfter;
536	  }
537	
538	  private parseUnary(cmd: Token, ctx: Ctx, afterOp?: Token): Expr {
539	    const signs: Token[] = [];
540	    let negative = false;
541	    for (;;) {
542	      const t = this.peek();
543	      if (t.kind === 'op' && (t.value === '+' || t.value === '-')) {
544	        signs.push(this.next());
545	        if (t.value === '-') negative = !negative;
546	      } else break;
547	    }
548	    const prim = this.parsePrimary(cmd, ctx, signs.length ? signs[signs.length - 1] : afterOp);
549	    if (!signs.length) return prim;
550	    return negative
551	      ? { k: 'neg', e: prim, tok: signs[0] }
552	      : { k: 'paren', e: prim, tok: signs[0] };
553	  }
554	
555	  private parsePrimary(cmd: Token, ctx: Ctx, prevTok?: Token): Expr {
556	    const t = this.next();
557	    this.checkLexError(t);
558	    switch (t.kind) {
559	      case 'num':
560	        return { k: 'num', v: t.value as number, tok: t };
561	      case 'cname':
562	        this.refs.push({ name: t.value as string, tok: t, scope: ctx.scope });
563	        return { k: 'var', name: t.value as string, tok: t };
564	      case 'lp': {
565	        if (this.parenDepth >= MAX_PAREN_DEPTH) {
566	          throw errAt(t, `Zbyt głębokie zagnieżdżenie nawiasów okrągłych (limit ${MAX_PAREN_DEPTH})`);
567	        }
568	        this.parenDepth++;
569	        const inner = this.parseExpr(cmd, ctx);
570	        this.parenDepth--;
571	        const c = this.peek();
572	        this.checkLexError(c);
573	        if (c.kind !== 'rp') {
574	          throw c.kind === 'eof'
575	            ? errAt(t, 'Nawias „(” nie został zamknięty – brakuje „)”')
576	            : errAt(c, `Oczekiwano „)” zamykającego nawias, a jest ${q(c)}`);
577	        }
578	        this.next();
579	        return { k: 'paren', e: inner, tok: t };
580	      }
581	      case 'ident': {
582	        const w = t.value as string;
583	        if (isRepcount(w)) {
584	          if (ctx.repDepth === 0) {
585	            throw errAt(
586	              t,
587	              `„${t.text}” można użyć tylko wewnątrz bloku powtórz [ … ] (w tej samej procedurze albo na najwyższym poziomie)`,
588	            );
589	          }
590	          return { k: 'rep', tok: t };
591	        }
592	        if (RESERVED.has(w)) {
593	          throw errAt(t, this.missingMessage(cmd, prevTok, `znaleziono polecenie „${t.text}”`));
594	        }
595	        this.refs.push({ name: w, tok: t, scope: ctx.scope });
596	        return { k: 'var', name: w, tok: t };
597	      }
