607	      return `Brakuje wartości po operatorze „${prevTok.text}” (${found})`;
608	    }
609	    return `Brakuje argumentu polecenia „${cmd.text}”: oczekiwano liczby, nazwy lub wyrażenia, ale ${found}`;
