  3	/** Błąd obliczania wyrażenia; wykonawca dołącza do niego położenie argumentu. */
  4	export class EvalError extends Error {}
  5	
  6	export interface EvalContext {
  7	  /** Wartość zmiennej; rzuca EvalError, gdy zmienna nie ma wartości. */
  8	  getVar(name: string): number;
  9	  /** Numer bieżącej iteracji najbliższego powtórz (1, 2, …). */
 10	  rep: number;
 11	}
 12	
 13	function finite(x: number): number {
 14	  if (!Number.isFinite(x)) throw new EvalError('Wynik działania nie jest skończoną liczbą');
 15	  return x;
 16	}
 17	
 18	export function evaluate(e: Expr, ctx: EvalContext): number {
 19	  switch (e.k) {
 20	    case 'num':
 21	      return e.v;
 22	    case 'var':
 23	      return ctx.getVar(e.name);
 24	    case 'rep':
 25	      return ctx.rep;
 26	    case 'paren':
 27	      return evaluate(e.e, ctx);
 28	    case 'neg':
 29	      return -evaluate(e.e, ctx);
 30	    case 'sum': {
 31	      let acc = evaluate(e.first, ctx);
 32	      for (const r of e.rest) {
 33	        const v = evaluate(r.e, ctx);
 34	        acc = finite(r.op === '+' ? acc + v : acc - v);
 35	      }
 36	      return acc;
 37	    }
 38	    case 'prod': {
 39	      let acc = evaluate(e.first, ctx);
 40	      for (const r of e.rest) {
 41	        const v = evaluate(r.e, ctx);
 42	        if (r.op === '*') acc = finite(acc * v);
 43	        else {
 44	          if (v === 0) throw new EvalError('Dzielenie przez zero');
 45	          acc = finite(acc / v);
 46	        }
 47	      }
 48	      return acc;
 49	    }
 50	  }
 51	}
 52	
 53	/** Czy wyrażenie jest zapisane samymi liczbami (bez nazw i nrpowt)? */
 54	export function isConstant(e: Expr): boolean {
 55	  switch (e.k) {
 56	    case 'num':
 57	      return true;
 58	    case 'var':
 59	    case 'rep':
 60	      return false;
 61	    case 'paren':
 62	    case 'neg':
 63	      return isConstant(e.e);
 64	    case 'sum':
 65	    case 'prod':
 66	      return isConstant(e.first) && e.rest.every((r) => isConstant(r.e));
 67	  }
 68	}
 69	
 70	const NO_VARS: EvalContext = {
 71	  getVar() {
 72	    throw new EvalError('Nazwa w wyrażeniu stałym');
 73	  },
 74	  rep: 1,
 75	};
 76	
 77	/** Wartość wyrażenia stałego albo `undefined`, gdy nie da się jej obliczyć. */
 78	export function constantValue(e: Expr): number | undefined {
 79	  if (!isConstant(e)) return undefined;
 80	  try {
 81	    return evaluate(e, NO_VARS);
 82	  } catch (err) {
 83	    if (err instanceof EvalError) return undefined;
 84	    throw err;
 85	  }
 86	}
 87	import { type Condition, type Expr, LogoError, type ProcDef, type Program, type Stmt } from './ast';
 88	import { EvalError, type EvalContext, evaluate } from './expr';
 89	import type { Mode } from './keywords';
 90	import type { Token } from './lexer';
 91	import { MAX_REPEAT, MAX_WIDTH } from './parser';
 92	
 93	export const MAX_OPS = 10_000;
 94	export const MAX_FRAMES = 32;
 95	export const MAX_SEGMENTS = 10_000;
 96	export const MAX_COORD = 100_000;
 97	
 98	export type Vec3 = [number, number, number];
 99	
100	export interface Segment {
101	  from: Vec3;
102	  to: Vec3;
103	  color: string;
104	  width: number;
105	}
106	
107	export interface TurtleState {
108	  pos: Vec3;
109	  /** Kierunek ruchu (nos żółwia). */
110	  fwd: Vec3;
111	  /** Prawa strona żółwia. */
112	  right: Vec3;
113	  /** Góra żółwia. */
114	  up: Vec3;
115	  penDown: boolean;
116	  color: string;
117	  width: number;
118	}
119	
120	/** Opis właśnie wykonanej operacji – do podświetlania wiersza. */
121	export interface Step {
122	  line: number;
123	  col: number;
124	}
125	
126	export const DEFAULT_COLOR = '#16866a';
127	export const DEFAULT_WIDTH = 3;
128	
129	export function initialTurtle(): TurtleState {
130	  return {
131	    pos: [0, 0, 0],
132	    fwd: [0, 1, 0],
133	    right: [1, 0, 0],
134	    up: [0, 0, 1],
135	    penDown: true,
136	    color: DEFAULT_COLOR,
137	    width: DEFAULT_WIDTH,
138	  };
139	}
140	
141	/** [sin, cos] kąta w stopniach – dokładne dla wielokrotności 90°. */
142	function sinCos(deg: number): [number, number] {
143	  const a = ((deg % 360) + 360) % 360;
144	  if (a === 0) return [0, 1];
145	  if (a === 90) return [1, 0];
146	  if (a === 180) return [0, -1];
147	  if (a === 270) return [-1, 0];
148	  const r = (deg * Math.PI) / 180;
149	  return [Math.sin(r), Math.cos(r)];
150	}
151	
152	/** Obrót pary wektorów: a' = a·cos + b·sin, b' = b·cos − a·sin. */
153	function rotatePair(a: Vec3, b: Vec3, deg: number): void {
154	  const [s, c] = sinCos(deg);
155	  for (let i = 0; i < 3; i++) {
156	    const ai = a[i];
157	    const bi = b[i];
158	    a[i] = ai * c + bi * s + 0;
159	    b[i] = bi * c - ai * s + 0;
160	  }
161	}
162	
163	interface Scope {
164	  /** Zmienne lokalne wywołania procedury; null na najwyższym poziomie. */
165	  locals: Map<string, number> | null;
166	}
167	
168	type Run = Generator<Step, boolean, undefined>;
169	
170	function at(tok: Token, message: string): LogoError {
171	  return new LogoError(message, tok.line, tok.col);
172	}
173	
174	export class Machine {
175	  turtle: TurtleState = initialTurtle();
176	  segments: Segment[] = [];
177	  ops = 0;
178	  private frames = 0;
179	  private globals = new Map<string, number>();
180	  private scope: Scope = { locals: null };
181	  private evalCtx: EvalContext;
182	
183	  constructor(
184	    private program: Program,
185	    readonly mode: Mode,
186	  ) {
187	    this.evalCtx = {
188	      rep: 1,
189	      getVar: (name) => {
190	        const loc = this.scope.locals;
191	        if (loc && loc.has(name)) return loc.get(name)!;
192	        const g = this.globals.get(name);
193	        if (g !== undefined) return g;
194	        throw new EvalError(`Zmienna „${name}” nie ma jeszcze wartości`);
195	      },
196	    };
197	  }
198	
199	  /** Wykonuje program; po każdej operacji zwraca jej położenie w kodzie. */
200	  *execute(): Generator<Step, void, undefined> {
201	    yield* this.block(this.program.body, 0);
202	  }
203	
204	  // ───────────────────────── pomocnicze ─────────────────────────
205	
206	  private tick(tok: Token): void {
207	    if (++this.ops > MAX_OPS) {
208	      throw at(tok, `Przekroczono limit ${MAX_OPS} wykonanych operacji`);
209	    }
210	  }
211	
212	  private num(e: Expr, rep: number): number {
213	    this.evalCtx.rep = rep;
214	    try {
215	      return evaluate(e, this.evalCtx);
216	    } catch (err) {
217	      if (err instanceof EvalError) throw at(e.tok, err.message);
218	      throw err;
219	    }
220	  }
221	
222	  private cond(c: Condition, rep: number): boolean {
223	    const l = this.num(c.left, rep);
224	    const r = this.num(c.right, rep);
225	    switch (c.op) {
226	      case '<':
227	        return l < r;
228	      case '>':
229	        return l > r;
230	      case '=':
231	        return l === r;
232	      case '<=':
233	        return l <= r;
234	      case '>=':
235	        return l >= r;
236	      case '<>':
237	        return l !== r;
238	    }
239	  }
240	
241	  private enterFrame(tok: Token): void {
242	    if (this.frames >= MAX_FRAMES) {
243	      throw at(
244	        tok,
245	        `Przekroczono limit ${MAX_FRAMES} jednocześnie aktywnych wywołań i powtórzeń (zbyt głęboka rekurencja?)`,
246	      );
247	    }
248	    this.frames++;
249	  }
250	
251	  // ───────────────────────── wykonanie ─────────────────────────
252	
253	  private *block(stmts: Stmt[], rep: number): Run {
254	    for (const s of stmts) {
255	      if (yield* this.stmt(s, rep)) return true;
256	    }
257	    return false;
258	  }
259	
260	  private *stmt(s: Stmt, rep: number): Run {
261	    const tok = s.tok;
262	    switch (s.t) {
263	      case 'cmd': {
264	        this.tick(tok);
265	        const stop = this.command(s, rep);
266	        yield { line: tok.line, col: tok.col };
267	        return stop;
268	      }
269	      case 'let': {
270	        this.tick(tok);
271	        const v = this.num(s.value, rep);
272	        const loc = this.scope.locals;
273	        if (loc) loc.set(s.name, v);
274	        else this.globals.set(s.name, v);
275	        yield { line: tok.line, col: tok.col };
276	        return false;
277	      }
278	      case 'repeat': {
279	        this.tick(tok);
280	        const n = this.num(s.count, rep);
281	        if (!Number.isInteger(n) || n < 0 || n > MAX_REPEAT) {
282	          throw at(s.count.tok, `Liczba powtórzeń musi być liczbą całkowitą od 0 do ${MAX_REPEAT}`);
283	        }
284	        this.enterFrame(tok);
285	        yield { line: tok.line, col: tok.col };
286	        for (let i = 1; i <= n; i++) {
287	          if (yield* this.block(s.body, i)) {
288	            this.frames--;
289	            return true;
290	          }
291	          this.tick(tok);
292	        }
293	        this.frames--;
294	        return false;
295	      }
296	      case 'if': {
297	        this.tick(tok);
298	        const holds = this.cond(s.cond, rep);
299	        yield { line: tok.line, col: tok.col };
300	        const body = holds ? s.then : s.else;
301	        if (body) {
302	          if (yield* this.block(body, rep)) return true;
303	          this.tick(tok);
304	        }
305	        return false;
306	      }
307	      case 'call': {
308	        this.tick(tok);
309	        const def = this.program.procs.get(s.proc) as ProcDef;
310	        const locals = new Map<string, number>();
311	        for (let i = 0; i < def.params.length; i++) {
312	          locals.set(def.params[i], this.num(s.args[i], rep));
313	        }
314	        this.enterFrame(tok);
315	        yield { line: tok.line, col: tok.col };
316	        const saved = this.scope;
317	        this.scope = { locals };
318	        try {
319	          yield* this.block(def.body, 0); // `stop` kończy tylko to wywołanie
320	        } finally {
321	          this.scope = saved;
322	        }
323	        this.frames--;
324	        this.tick(tok);
325	        return false;
326	      }
327	    }
328	  }
329	
330	  /** Wykonuje polecenie; zwraca true dla `stop`. */
331	  private command(s: Extract<Stmt, { t: 'cmd' }>, rep: number): boolean {
332	    const t = this.turtle;
333	    switch (s.op) {
334	      case 'fd':
335	        this.move(this.num(s.arg!, rep), s.tok);
336	        break;
337	      case 'bk':
338	        this.move(-this.num(s.arg!, rep), s.tok);
339	        break;
340	      case 'rt':
341	        rotatePair(t.fwd, t.right, this.num(s.arg!, rep));
342	        break;
343	      case 'lt':
344	        rotatePair(t.fwd, t.right, -this.num(s.arg!, rep));
345	        break;
346	      case 'pitchup':
347	        rotatePair(t.fwd, t.up, this.num(s.arg!, rep));
348	        break;
349	      case 'pitchdown':
350	        rotatePair(t.fwd, t.up, -this.num(s.arg!, rep));
351	        break;
352	      case 'rr':
353	        rotatePair(t.up, t.right, this.num(s.arg!, rep));
354	        break;
355	      case 'rl':
356	        rotatePair(t.up, t.right, -this.num(s.arg!, rep));
357	        break;
358	      case 'pu':
359	        t.penDown = false;
360	        break;
361	      case 'pd':
362	        t.penDown = true;
363	        break;
364	      case 'color':
365	        t.color = s.color!;
366	        break;
367	      case 'width': {
368	        const w = this.num(s.arg!, rep);
369	        if (!Number.isInteger(w) || w < 1 || w > MAX_WIDTH) {
370	          throw at(s.arg!.tok, `Grubość musi być liczbą całkowitą od 1 do ${MAX_WIDTH}`);
371	        }
372	        t.width = w;
373	        break;
374	      }
375	      case 'stop':
376	        return true;
377	      case 'home':
378	        this.goTo([0, 0, 0], s.tok);
379	        t.fwd = [0, 1, 0];
380	        t.right = [1, 0, 0];
381	        t.up = [0, 0, 1];
382	        break;
383	      case 'cs':
384	        this.segments.length = 0;
385	        break;
386	    }
387	    return false;
388	  }
389	
390	  private move(distance: number, tok: Token): void {
391	    const t = this.turtle;
392	    const to: Vec3 = [
393	      t.pos[0] + t.fwd[0] * distance + 0,
394	      t.pos[1] + t.fwd[1] * distance + 0,
395	      t.pos[2] + t.fwd[2] * distance + 0,
396	    ];
397	    this.goTo(to, tok);
398	  }
399	
400	  private goTo(to: Vec3, tok: Token): void {
401	    const t = this.turtle;
402	    for (let i = 0; i < 3; i++) {
403	      if (!Number.isFinite(to[i]) || Math.abs(to[i]) > MAX_COORD) {
404	        throw at(tok, `Współrzędna wykracza poza dozwolony zakres ±${MAX_COORD}`);
405	      }
406	    }
407	    const from = t.pos;
408	    if (t.penDown && (from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2])) {
409	      if (this.segments.length >= MAX_SEGMENTS) {
410	        throw at(tok, `Przekroczono limit ${MAX_SEGMENTS} odcinków rysunku`);
411	      }
412	      this.segments.push({
413	        from: [from[0], from[1], from[2]],
414	        to: [to[0], to[1], to[2]],
415	        color: t.color,
416	        width: t.width,
417	      });
418	    }
419	    t.pos = to;
420	  }
421	}

