private async openDroppedFile(file: File): Promise<void> {
  try {
    const { text, name } = await readTextFile(file);
    await this.loadText(text, name);
  } catch (e) {
    toast(e instanceof Error ? e.message : 'Nie udało się otworzyć pliku.', { kind: 'error' });
  }
}

